                        right:       0,
                        width:      '100%',
                        height:     cssVars.spacing.l,
                        background: 'transparent',
                        border:     'none',
                        outline:    'none',
                        fontFamily:  FONT,
                        fontWeight:  cssVars.font.weight.regular,
                        fontSize:    cssVars.font.size['2xs'],
                        color:       textColour,
                        padding:     0,
                        opacity:     floated ? 1 : 0,
                        cursor:      disabled ? 'not-allowed' : 'text',
                        transition: `opacity ${cssVars.motion.duration.fast} ${cssVars.motion.easing.standard}`,
                    }}
                />
            </div>
            {/* Figma: built-in clear-✕, shown whenever there's a value and the field isn't disabled */}
            {!disabled && value.length > 0 && (
                <chakra.button
                    type="button"
                    aria-label="Clear input"
                    onClick={handleClear}
                    sx={{
                        background:     'transparent',
                        border:         'none',
                        padding:         0,
                        cursor:         'pointer',
                        display:        'inline-flex',
                        alignItems:     'center',
                        justifyContent: 'center',
                        flexShrink:      0,
                        color:           textColour,
                        minWidth:        cssVars.spacing.xl,
                        minHeight:       cssVars.spacing.xl,
                        // WCAG 2.2 AA SC 2.4.7 — visible focus state
                        _focusVisible: {
                            outline:       inverse ? `${cssVars.border.width} solid ${cssVars.color.action.primary.text}` : cssVars.focusRing,
                            outlineOffset: cssVars.focusRingOffset.default,
                            boxShadow:     'none',
                        },
                    }}
                >
                    <ZimmIcon type="close" size="sm" aria-hidden={true} />
                </chakra.button>
            )}
            {trailing}
        </chakra.div>
        {helperText && (
            <p id={helperId} style={{margin: `${cssVars.spacing['2xs']} 0 0`, fontFamily: FONT, fontSize: cssVars.font.size['3xs'], color: inverse ? cssVars.color.text.inverseGrey : cssVars.color.text.secondary}}>
                {helperText}
            </p>
        )}
        {errorText && (
            <p id={errorId} role="alert" style={{
                margin:     `${cssVars.spacing['2xs']} 0 0`,
                fontFamily:  FONT,
                fontSize:    cssVars.font.size['2xs'],
                fontStyle:  'normal',
                fontWeight:  cssVars.font.weight.regular,
                lineHeight:  cssVars.font.lineHeight['2xs'],
                color:       inverse ? cssVars.color.status.errorBackground : cssVars.color.status.error,
            }}>
                {errorText}
            </p>
        )}
    </div>
)

