import {useRef, useState} from 'react'
import type React from 'react'
import {cssVars} from 'app/utils/cssVars'

// Figma Textfield flush variant (node 40000265:374): field/border/* tokens.
// hover and filled (has value, unfocused) both darken to focus colour per Figma spec.
const BORDER = {
    default: cssVars.color.border.forms,  // #707070 — Figma field/border/default
    hover:   cssVars.color.border.focus,  // #191919 — Figma field/border/hover
    filled:  cssVars.color.border.focus,  // #191919 — Figma field/border/filled
    focus:   cssVars.color.border.focus,  // #191919 — Figma field/border/focus
    error:   cssVars.color.border.error,  // #9c0000 — Figma field/border/error
} as const

// Figma field/border/inverse/default = white (opaque), inverse/error = #f98f8c (coral).
// Figma does not spec inverse/hover or inverse/focus separately — use same white.
const BORDER_INVERSE = {
    default: cssVars.color.text.inverse,           // white  — Figma field/border/inverse/default
    hover:   cssVars.color.text.inverse,           // white  — Figma (not separately spec'd, same as default)
    filled:  cssVars.color.text.inverse,           // white  — Figma (not separately spec'd)
    focus:   cssVars.color.text.inverse,           // white  — Figma field/border/inverse/focus
    error:   cssVars.color.status.errorBackground, // #f98f8c — Figma field/border/inverse/error
} as const

type UseZimmTextInputStateParams = {
    inverse:   boolean
    disabled:  boolean
    hasError:  boolean
    onChange?: (value: string) => void
    /** Controlled value. When provided the caller owns the value and internal state is unused. */
    value?:        string
    /** Seed for the uncontrolled case. Ignored when `value` is provided. */
    defaultValue?: string
}

type UseZimmTextInputStateReturn = {
    value:        string
    focused:      boolean
    floated:      boolean
    borderColour: string
    /** hover border colour — used by the component to apply :hover via CSS (chakra sx) */
    hoverBorderColour: string
    labelColour:  string
    inputRef:     React.RefObject<HTMLInputElement>
    handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    handleClear:  () => void
    setFocused:   React.Dispatch<React.SetStateAction<boolean>>
}

/**
 * Manages interaction state for ZimmTextInput — value, focus, and derived
 * border/label colours aligned to Figma Textfield flush tokens (node 40000265:374).
 * Hover border is no longer managed as JS state — the component applies it via
 * CSS pseudo-class (chakra sx `_hover`) to avoid a useState round-trip per mouse event.
 *
 * Supports both modes, following the React convention: pass `value` to control it from a
 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
 * seeded from `defaultValue`. `onChange` fires in both modes.
 * @returns value, focus flag, derived visual tokens, inputRef, and event handlers
 */
export const useZimmTextInputState = ({
    inverse,
    disabled,
    hasError,
    onChange,
    value: controlledValue,
    defaultValue,
}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
    // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
    // `defaultValue`. Reading `value` through this indirection keeps every derived token
    // below (floated, borderColour, labelColour) correct in both modes.
    const isControlled = controlledValue !== undefined
    const [internalValue, setInternalValue] = useState(defaultValue ?? '')
    const value = isControlled ? controlledValue : internalValue
    const [focused, setFocused] = useState(false)
    const inputRef = useRef<HTMLInputElement>(null)

    const floated = focused || value.length > 0
    const palette = inverse ? BORDER_INVERSE : BORDER

    const borderColour = (() => {
        if (disabled)         return palette.default
        if (hasError)         return palette.error
        if (focused)          return palette.focus
        if (value.length > 0) return palette.filled
        return palette.default
    })()

    // When in error state, hover keeps the error colour (error > hover in priority).
    // In all other states, hover darkens to focus colour — same value as focus itself.
    const hoverBorderColour = hasError ? borderColour : palette.hover

    // Figma text/subtle = #666 (colors.text.secondary) for floated/disabled label in light mode.
    // Figma text/inverse/subtle = #969696 (colors.text.inverseGrey) for floated/disabled label in inverse mode.
    const labelColour = (() => {
        if (disabled) return inverse ? cssVars.color.text.inverseGrey : cssVars.color.text.secondary
        if (inverse)  return floated ? cssVars.color.text.inverseGrey : cssVars.color.text.inverse
        return floated ? cssVars.color.text.secondary : cssVars.color.text.default
    })()

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (!isControlled) setInternalValue(e.target.value)
        onChange?.(e.target.value)
    }

    const handleClear = () => {
        if (!isControlled) setInternalValue('')
        onChange?.('')
        inputRef.current?.focus()
    }

    return {
        value, focused, floated,
        borderColour, hoverBorderColour, labelColour,
        inputRef,
        handleChange, handleClear,
        setFocused,
    }
}

