const F = require(process.env.CLAUDE_JOB_DIR + '/tmp/foundation.cjs');

// value (normalised) -> [token paths]
const index = new Map();
const add = (val, path) => {
  const k = norm(val);
  if (k === null) return;
  if (!index.has(k)) index.set(k, []);
  index.get(k).push(path);
};

function norm(v) {
  if (typeof v === 'number') return `n:${v}`;
  if (typeof v !== 'string') return null;
  const s = v.trim().toLowerCase();
  if (s.startsWith('var(')) return null;                  // reference, not a value
  let m;
  if ((m = s.match(/^(-?[\d.]+)px$/)))  return `len:${(+m[1]).toFixed(4)}`;
  if ((m = s.match(/^(-?[\d.]+)rem$/))) return `len:${(+m[1]*16).toFixed(4)}`;
  if ((m = s.match(/^(-?[\d.]+)em$/)))  return `len:${(+m[1]*16).toFixed(4)}`;
  if ((m = s.match(/^(-?[\d.]+)ms$/)))  return `ms:${+m[1]}`;
  if ((m = s.match(/^#([0-9a-f]{3})$/))) return `col:#${m[1].split('').map(c=>c+c).join('')}`;
  if ((m = s.match(/^#([0-9a-f]{6})$/))) return `col:#${m[1]}`;
  if ((m = s.match(/^rgba?\(([^)]+)\)$/))) {
    const p = m[1].split(',').map(x=>x.trim());
    const a = p[3] === undefined ? '1' : String(+p[3]);
    return `col:rgba(${+p[0]},${+p[1]},${+p[2]},${a})`;
  }
  if (/^[\d.]+$/.test(s)) return `n:${+s}`;
  return `s:${s}`;
}

function walk(obj, path) {
  if (obj === null || obj === undefined) return;
  if (typeof obj !== 'object') { add(obj, path); return; }
  for (const [k, v] of Object.entries(obj)) walk(v, path ? `${path}.${k}` : k);
}

for (const [name, val] of Object.entries(F)) {
  if (name === 'zimmTokens') { for (const [k,v] of Object.entries(val)) walk(v, `zimmTokens[${k}]`); }
  else walk(val, name);
}
module.exports = { index, norm };
EOF
