const fs = require('fs');
const path = require('path');
const DIR = 'overrides/app/theme/components';

// Literal patterns we care about (design values). Excludes anything inside var(...).
const LIT = /(?:'|")(#[0-9a-fA-F]{3,8}|rgba?\([^)']*\)|-?[\d.]+(?:px|rem|em|ms|s)\b)(?:'|")/g;

const rows = [];
for (const f of fs.readdirSync(DIR).filter(f => f.endsWith('.ts') && !f.endsWith('.test.ts') && f !== 'index.ts')) {
  const full = path.join(DIR, f);
  const src = fs.readFileSync(full, 'utf8');
  const lines = src.split('\n');

  lines.forEach((line, i) => {
    const lineNo = i + 1;
    // strip var(--x) refs and // comments' var refs so we only see raw literals
    const stripped = line.replace(/var\(--[a-z0-9-]+\)/gi, 'VAR');
    const isComment = /^\s*(\/\/|\*|\/\*)/.test(line);

    // module-level const NAME = <literal>
    let m = line.match(/^const\s+([A-Z][A-Z_0-9]*)\s*=\s*(.+?);?\s*(?:\/\/.*)?$/);
    if (m && !m[2].startsWith('{')) {
      const raw = m[2].replace(/;$/, '').trim();
      rows.push({file: f, line: lineNo, kind: 'const', name: m[1], raw, comment: (line.match(/\/\/\s*(.*)$/)||[])[1]||''});
      return;
    }
    // object member inside a const NAME = { ... }  (e.g. BP.tablet)
    m = line.match(/^\s{2,}([a-zA-Z][a-zA-Z0-9]*)\s*:\s*'([^']+)'\s*,?\s*(?:\/\/\s*(.*))?$/);
    if (m && /^-?[\d.]+(px|rem|em|ms)$|^#|^rgba?\(/.test(m[2])) {
      rows.push({file: f, line: lineNo, kind: 'member', name: m[1], raw: `'${m[2]}'`, comment: m[3]||''});
      return;
    }
    // inline raw literal anywhere else (recipe body)
    if (isComment) return;
    let lm;
    while ((lm = LIT.exec(stripped))) {
      rows.push({file: f, line: lineNo, kind: 'inline', name: (line.match(/^\s*([a-zA-Z][\w]*)\s*:/)||[])[1] || '(inline)', raw: `'${lm[1]}'`, comment: ''});
    }
  });
}
module.exports = rows;
if (require.main === module) {
  console.log('total extracted:', rows.length);
  rows.forEach(r => console.log(`${r.file}:${r.line} [${r.kind}] ${r.name} = ${r.raw} ${r.comment ? '// '+r.comment : ''}`));
}
EOF
