import React from 'react';
import type { Meta, StoryObj } from '@storybook/react';
import { expect, userEvent, within } from 'storybook/test';
import { Footer } from './index';
import { FOOTER_FIXTURE } from './contentfulFixture';

const meta: Meta<typeof Footer> = {
  title: 'Layout/Footer',
  component: Footer,
  parameters: {
    layout: 'fullscreen',
  },
  args: {
    data: FOOTER_FIXTURE,
  },
};

export default meta;
type Story = StoryObj<typeof Footer>;

export const Default: Story = {
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
};

export const Subscribed: Story = {
  args: {
    initialSubscribed: true,
  },
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} />
    </div>
  ),
};

export const SubscribeSubmit: Story = {
  name: 'Subscribe — full two-step flow',
  render: (args) => (
    <div style={{ width: '100%' }}>
      <Footer {...args} privacyPolicyHref="/privacy-policy" />
    </div>

