import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React from 'react';
import { expect, fn, userEvent, within } from 'storybook/test';
import { Box } from '@chakra-ui/react';
import { ZimmButton } from '.';
import type { ZimmIconType } from '../zimmIcon';

const ALL_ICONS: ZimmIconType[] = [
  'arrow-down',
  'arrow-link',
  'arrow-up',
  'bag',
  'bag-selected',
  'calendar',
  'carousel',
  'carousel-selected',
  'chat',
  'check',
  'chevron-down',
  'chevron-left',
  'chevron-right',
  'chevron-up',
  'close',
  'delete',
  'edit',
  'external-link',
  'info',
  'info-selected',
  'location',
  'menu',
  'minus',
  'mute',
  'password',
  'pause',
  'play',
  'plus',
  'profile',
  'search',
  'share',
  'share-2',
  'wishlist',
  'wishlist-selected',
  'phone',
  'whatsapp',
  'email',
];

const meta: Meta<typeof ZimmButton> = {
  title: 'Elements/ZimmButton',
  component: ZimmButton,
  argTypes: {
    variant: {
      control: 'select',
      options: ['primary', 'secondary', 'icon'],
    },
    size: {
      control: 'select',
      options: ['large', 'medium', 'sm', 'md', 'lg'],
    },
    icon: {
      control: 'select',
      options: ALL_ICONS,
    },
    inverse: {
      control: 'boolean',
    },
    disabled: {
      control: 'boolean',
    },
    fullWidth: {
      control: 'boolean',
    },
    type: {
      control: 'radio',
      options: ['button', 'submit', 'reset'],
    },
    style: {
      control: 'object',
    },
  },
};
export default meta;

type Story = StoryObj<typeof ZimmButton>;

const inverseDecorator = [
  (Story: React.ComponentType) => (
    <Box bg="background.05" p={4} display="inline-flex">
      <Story />
    </Box>
  ),
];

// ─── Primary ────────────────────────────────────────────────────────────────

export const Default: Story = {
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
  },
};

export const PrimaryMedium: Story = {
  name: 'Primary — Medium',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'medium',
  },
};

export const PrimaryDisabled: Story = {
  name: 'Primary — Disabled',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    disabled: true,
  },
};

export const PrimaryInverse: Story = {
  name: 'Primary — Inverse',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    inverse: true,
  },
  decorators: inverseDecorator,
};

export const PrimaryFullWidth: Story = {
  name: 'Primary — Full Width',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    fullWidth: true,
  },
};

// ─── Secondary ──────────────────────────────────────────────────────────────

export const Secondary: Story = {
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'large',
  },
};

export const SecondaryMedium: Story = {
  name: 'Secondary — Medium',
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'medium',
  },
};

export const SecondaryDisabled: Story = {
  name: 'Secondary — Disabled',
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'large',
    disabled: true,
  },
};

export const SecondaryInverse: Story = {
  name: 'Secondary — Inverse',
  args: {
    variant: 'secondary',
    label: 'Button',
    size: 'large',
    inverse: true,
  },
  decorators: inverseDecorator,
};

// ─── Icon ───────────────────────────────────────────────────────────────────

export const Icon: Story = {
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'md',
  },
};

export const IconSmall: Story = {
  name: 'Icon — Small',
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'sm',
  },
};

export const IconLarge: Story = {
  name: 'Icon — Large',
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'lg',
  },
};

export const IconDisabled: Story = {
  name: 'Icon — Disabled',
  args: {
    variant: 'icon',
    icon: 'chevron-right',
    label: 'Next',
    size: 'md',
    disabled: true,
  },
};

export const IconInverse: Story = {
  name: 'Icon — Inverse',
  args: {
    variant: 'icon',
    icon: 'search',
    label: 'Search',
    size: 'md',
    inverse: true,
  },
  decorators: inverseDecorator,
};

// ─── Common icon use-cases ───────────────────────────────────────────────────

export const Bag: Story = {
  args: {
    variant: 'icon',
    icon: 'bag',
    label: 'Open bag',
    size: 'lg',
  },
};

export const Close: Story = {
  args: {
    variant: 'icon',
    icon: 'close',
    label: 'Close',
    size: 'md',
  },
};

export const Menu: Story = {
  args: {
    variant: 'icon',
    icon: 'menu',
    label: 'Open menu',
    size: 'lg',
  },
};

export const Wishlist: Story = {
  args: {
    variant: 'icon',
    icon: 'wishlist',
    label: 'Add to wishlist',
    size: 'lg',
  },
};

export const WishlistSelected: Story = {
  name: 'Wishlist Selected',
  args: {
    variant: 'icon',
    icon: 'wishlist-selected',
    label: 'Remove from wishlist',
    size: 'lg',
  },
};

// ─── style prop samples ──────────────────────────────────────────────────────

export const StyleBorderRadius: Story = {
  name: 'Style — Border Radius',
  args: {
    variant: 'primary',
    label: 'Button',
    size: 'large',
    style: { borderRadius: '24px' },
  },
};

export const StyleIconPadding: Story = {
  name: 'Style — Icon Padding',
  args: {
    variant: 'icon',
    icon: 'close',
    label: 'Close',
    size: 'md',
    style: { padding: '4px' },
  },
};

// ─── Interaction ─────────────────────────────────────────────────────────────

export const ClickInteraction: Story = {
  name: 'Click Interaction',
  args: {
    variant: 'primary',
    label: 'Add to bag',
    size: 'large',
    onClick: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const button = canvas.getByRole('button', { name: 'Add to bag' });
    await userEvent.click(button);
    await expect(args.onClick).toHaveBeenCalledOnce();
  },
};

export const IconClickInteraction: Story = {
  name: 'Icon Click Interaction',
  args: {
    variant: 'icon',
    icon: 'bag',
    label: 'Add to bag',
    size: 'lg',
    onClick: fn(),
  },
  play: async ({ canvasElement, args }) => {
    const canvas = within(canvasElement);
    const button = canvas.getByRole('button', { name: 'Add to bag' });
    await userEvent.click(button);
    await expect(args.onClick).toHaveBeenCalledOnce();
  },
};

