42	const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
43	const ACCESSIBILITY_DISCLAIMER_COPY =
44	  'Zimmermann is committed to providing accessible services. ' +
45	  'If you experience any difficulty, please contact us for assistance.';
46	
47	type SubscribeModalProps = {
48	  isOpen: boolean;
49	  onClose: () => void;
50	  onSubmit: (firstName: string, lastName: string) => void;
51	  privacyPolicyHref: string;
52	};
53	
54	const SubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: SubscribeModalProps) => {
55	  const [mounted, setMounted] = useState(false);
56	  const formRef = useRef<HTMLFormElement>(null);
57	  const firstFocusRef = useRef<HTMLDivElement>(null);
58	  const triggerRef = useRef<Element | null>(null);
59	  const styles = useMultiStyleConfig('Footer', {});
60	
61	  useEffect(() => {
62	    setMounted(true);
63	  }, []);
64	
65	  // Save the trigger element on open so focus can be restored on close
66	  useEffect(() => {
67	    if (isOpen) {
68	      triggerRef.current = document.activeElement;
69	      // Defer so the portal has rendered before we try to focus inside it
70	      const id = setTimeout(() => {
71	        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
72	        firstInput?.focus();
73	      }, 0);
74	      return () => clearTimeout(id);
75	    } else {
76	      // Return focus to the element that opened the modal
77	      if (triggerRef.current instanceof HTMLElement) {
78	        triggerRef.current.focus();
79	      }
80	    }
81	  }, [isOpen]);
82	
83	  // Lock body scroll while modal is open
84	  useEffect(() => {
85	    if (!isOpen) return;
86	    const prev = document.body.style.overflow;
87	    document.body.style.overflow = 'hidden';
88	    return () => {
89	      document.body.style.overflow = prev;
90	    };
91	  }, [isOpen]);
92	
93	  // Keyboard: Escape to close, Tab trap within modal
94	  const handleKeyDown = useCallback(
95	    (e: KeyboardEvent) => {
96	      if (e.key === 'Escape') {
97	        onClose();
98	        return;
99	      }
100	      if (e.key !== 'Tab' || !formRef.current) return;
101	
102	      const focusable = Array.from(
103	        formRef.current.querySelectorAll<HTMLElement>(
104	          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
105	        ),
106	      ).filter((el) => !el.hasAttribute('disabled'));
107	
108	      const first = focusable[0];
109	      const last = focusable[focusable.length - 1];
110	
111	      if (e.shiftKey && document.activeElement === first) {
112	        e.preventDefault();
113	        last?.focus();
114	      } else if (!e.shiftKey && document.activeElement === last) {
115	        e.preventDefault();
116	        first?.focus();
117	      }
118	    },
119	    [onClose],
120	  );
121	
122	  useEffect(() => {
123	    if (!isOpen) return;
124	    document.addEventListener('keydown', handleKeyDown);
125	    return () => document.removeEventListener('keydown', handleKeyDown);
126	  }, [isOpen, handleKeyDown]);
127	
128	  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
129	    e.preventDefault();
130	    const form = e.currentTarget;
131	    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement)?.value ?? '';
132	    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement)?.value ?? '';
133	    onSubmit(firstName.trim(), lastName.trim());
134	  };
135	
136	  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
137	    if (e.target === e.currentTarget) onClose();
138	  };
139	
140	  if (!mounted || !isOpen) return null;
141	
142	  return createPortal(
143	    <chakra.div role="presentation" onClick={handleBackdropClick} __css={styles.modalOverlay}>
144	      <chakra.div
145	        role="dialog"
146	        aria-modal="true"
147	        aria-labelledby="zimm-subscribe-modal-title"
148	        aria-describedby="zimm-subscribe-modal-consent"
149	        __css={styles.subscribeModalPanel}
150	      >
151	        <form ref={formRef} onSubmit={handleFormSubmit} noValidate>
152	          {/* Title */}
153	          <chakra.h2 id="zimm-subscribe-modal-title" __css={styles.modalTitle}>
154	            Join Us
155	          </chakra.h2>
156	
157	          {/* First Name */}
158	          <chakra.div ref={firstFocusRef} __css={styles.modalField}>
159	            <ZimmTextInput label="First Name" name="firstName" />
160	          </chakra.div>
161	
162	          {/* Last Name */}
163	          <chakra.div __css={styles.modalFieldLast}>
164	            <ZimmTextInput label="Last Name" name="lastName" />
165	          </chakra.div>
