cd "$CLAUDE_JOB_DIR/tmp"; curl -s --max-time 25 http://localhost:3000/ -o L2.html
cat > layer2.cjs <<'EOF'
const fs=require('fs');
const {index,norm}=require(process.env.CLAUDE_JOB_DIR+'/tmp/tokenIndex.cjs');
const h=fs.readFileSync(process.env.CLAUDE_JOB_DIR+'/tmp/L2.html','utf8');
const css=[...h.matchAll(/<style[^>]*data-emotion[^>]*>([\s\S]*?)<\/style>/g)].map(m=>m[1]).join('\n');

// 1. all classes inside the <footer> subtree
const foot=/<footer[\s\S]*?<\/footer>/.exec(h)[0];
const classes=[...new Set([...foot.matchAll(/class="([^"]+)"/g)].flatMap(m=>m[1].split(/\s+/)).filter(c=>c.startsWith('css-')))];

// 2. every rule (incl. pseudo + media) touching those classes
const defs=new Set([...h.matchAll(/(--[a-z0-9-]+)\s*:/gi)].map(m=>m[1]));
const rules=[];
for(const c of classes){
  const re=new RegExp('\\.'+c+'(:[a-z-]+(\\([^)]*\\))?)?\\{([^}]*)\\}','g');
  let m; while((m=re.exec(css))) rules.push({cls:c, pseudo:m[1]||'', decls:m[3]});
}

// 3. classify each declaration value
const SAFE_KEYWORD=/^(auto|none|inherit|initial|unset|currentColor|transparent|block|flex|inline-flex|inline-block|grid|column|row|nowrap|wrap|center|flex-start|flex-end|space-between|space-around|baseline|absolute|relative|fixed|sticky|static|hidden|visible|clip|scroll|pointer|text|uppercase|lowercase|capitalize|normal|bold|italic|solid|dashed|dotted|underline|left|right|top|bottom|middle|content-box|border-box|0|0px|1|100%|full|fit-content|max-content|min-content|-webkit-box|-ms-flexbox|-webkit-inline-box|-ms-inline-flexbox|-webkit-flex|-webkit-inline-flex)$/i;
const buckets={zimm:0, chakra:0, tokenEquivLiteral:0, keyword:0, structural:0, FLAG:[]};
const seen=new Set();
for(const r of rules){
  for(const d of r.decls.split(';')){
    if(!d.trim())continue;
    const i=d.indexOf(':'); if(i<0)continue;
    const prop=d.slice(0,i).trim(), val=d.slice(i+1).trim();
    if(/^-(webkit|moz|ms)-/.test(prop)) continue;              // vendor dupes
    if(val.includes('var(--zimm-')){ buckets.zimm++; 
      for(const v of val.matchAll(/var\((--zimm-[a-z0-9-]+)/g)) if(!defs.has(v[1])) buckets.FLAG.push(`UNDEFINED VAR  .${r.cls}${r.pseudo}  ${prop}: ${val}`);
      continue; }
    if(val.includes('var(--chakra-')){ buckets.chakra++;
      for(const v of val.matchAll(/var\((--chakra-[a-z0-9-]+)/g)) if(!defs.has(v[1])) buckets.FLAG.push(`UNDEFINED VAR  .${r.cls}${r.pseudo}  ${prop}: ${val}`);
      continue; }
    if(SAFE_KEYWORD.test(val)){ buckets.keyword++; continue; }
    // structural / non-design props we don't police
    if(/^(display|position|top|right|bottom|left|inset|overflow|z-index|flex|flex-\w+|order|grid[\w-]*|align\w*|justify\w*|list-style|white-space|cursor|content|pointer-events|box-sizing|text-decoration|text-transform|text-align|vertical-align|transform|transition|will-change|visibility|appearance|outline-offset|object-fit|aspect-ratio)$/.test(prop)){ buckets.structural++; continue; }
    const k=norm(val);
    const hit=k && index.get(k);
    const key=`${prop}|${val}`;
    if(hit){ buckets.tokenEquivLiteral++; if(!seen.has(key)){seen.add(key);} continue; }
    if(!seen.has(key)){ seen.add(key); buckets.FLAG.push(`NO TOKEN      .${r.cls}${r.pseudo}  ${prop}: ${val}`); }
  }
}
console.log('############ LAYER 2 — EMITTED CSS AUDIT ############');
console.log('footer classes:',classes.length,'| rules (incl. pseudo/media):',rules.length,'\n');
console.log('  var(--zimm-*)              ',buckets.zimm);
console.log('  var(--chakra-*)            ',buckets.chakra);
console.log('  literal == a token value   ',buckets.tokenEquivLiteral);
console.log('  CSS keyword / structural   ',buckets.keyword+buckets.structural);
console.log('');
console.log(buckets.FLAG.length? '❌ FLAGGED ('+buckets.FLAG.length+' distinct):':'✅ NOTHING FLAGGED');
[...new Set(buckets.FLAG)].sort().forEach(f=>console.log('   '+f));
EOF
