import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
for (const w of [1440, 1023, 402]) {
  const p = await b.newPage({ viewport:{width:w,height:900} });
  await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded', timeout:60000 });
  await p.waitForSelector('footer[role="contentinfo"]');
  const r = await p.evaluate(() => {
    const f = document.querySelector('footer[role=contentinfo]');
    const navs = [...f.querySelectorAll('ul a')];
    const legal = [...f.querySelectorAll('div > a')].filter(a=>/ACCESS|TERMS|PRIVACY|SLAVERY|COOKIE/i.test(a.textContent));
    const ack = navs.find(a=>/ACKNOWLEDGEMENT/i.test(a.textContent));
    const box = e => { const r = e.getBoundingClientRect(); return Math.round(r.height); };
    return {
      inlineStyles: navs.filter(a=>a.getAttribute('style')).length,
      navHeights: [...new Set(navs.map(box))].sort((a,b)=>a-b),
      ackHeight: ack ? box(ack) : null,
      ackLines: ack ? Math.round(box(ack) / parseFloat(getComputedStyle(ack).lineHeight || 16)) : null,
      minHeightApplied: navs[0] ? getComputedStyle(navs[0]).minHeight : null,
      whiteSpace: navs[0] ? getComputedStyle(navs[0]).whiteSpace : null,
      legalHeights: [...new Set(legal.map(box))],
      footerH: Math.round(f.getBoundingClientRect().height),
    };
  });
  console.log(`\n${w}px  ${JSON.stringify(r)}`);
  await p.close();
}
await b.close();
EOF
