import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
const p = await b.newPage({ viewport:{width:1440,height:900} });
await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded', timeout:60000 });
await p.waitForSelector('footer[role="contentinfo"]');
const r = await p.evaluate(() => {
  const f=document.querySelector('footer[role=contentinfo]');
  const col=[...f.querySelectorAll('ul')].map(u=>u.parentElement).find(c=>/CONTACT/i.test(c.textContent));
  const base=col.getBoundingClientRect().left;
  const L=e=>Math.round(e.getBoundingClientRect().left-base);
  // heading TEXT edge, not box edge: use a Range over the text node
  const h=col.querySelector('p'); const rg=document.createRange(); rg.selectNodeContents(h);
  return {
    headingTextEdge: Math.round(rg.getBoundingClientRect().left-base),
    itemTextEdges: [...col.querySelectorAll('ul a span')].map(L),
    iconBoxEdge:  L(f.querySelector('svg[aria-label="Call us"]').closest('span')),
    iconGlyphEdge: L(f.querySelector('svg[aria-label="Call us"]')),
  };
});
console.log(JSON.stringify(r,null,1));
const all=[r.headingTextEdge,...r.itemTextEdges,r.iconGlyphEdge];
console.log('\nall visible left edges:', all.join(', '), new Set(all).size===1 ? '→ ALIGNED ✅' : '→ NOT aligned ❌');
await b.close();
EOF
