  const cls=m[1], body=consts[m[2]];
  if(!body) continue;
  // class name -> textStyle key
  const key=camel(cls.replace('zimm-text-','')).replace(/^h([1-3])(Strong)?$/,(_,n,s)=>'heading'+n+(s||''));
