import React from 'react'

// Populated at SSR module-init time via a webpackIgnore'd dynamic import so Webpack
// never traces the SSR-only module chain (pwa-kit-runtime → cosmiconfig → fs) into
// the browser/Storybook bundle. Real PWA Kit builds define a WEBPACK_TARGET constant
// that lets that chain get dead-code-eliminated from a *static* import — but Storybook's
// webpack config doesn't define it, so a plain top-level import of this SDK module would
// drag cosmiconfig/fs into the Storybook bundle and fail to resolve. Kept SSR-only for
// that reason; the browser gets its own path below instead of importing this module.
let _getAssetUrl: ((path: string) => string) | undefined

if (typeof window === 'undefined') {
    void import(/* webpackIgnore: true */ '@salesforce/pwa-kit-react-sdk/ssr/universal/utils')
        .then((m) => { _getAssetUrl = m.getAssetUrl })
        .catch(() => {})
}

// Resolves the correct bundle-prefixed URL in the PWA Kit dev server and production.
// SSR: uses the dynamically-imported getAssetUrl above.
// Browser: reads window.Progressive.buildOrigin directly instead of importing the SDK
// module (see comment above) — it's the exact same value getAssetUrl itself would use
// client-side, set by the PWA Kit client runtime before hydration.
// Falls back to a bare path in environments with neither (e.g. Storybook), where the font
// 404s silently and the system fallback font is used instead.
const fontUrl = (filename: string): string => {
    const path = `static/fonts/${filename}`

    if (_getAssetUrl) {
        try { return _getAssetUrl(path) } catch {}
    }

    if (typeof window !== 'undefined') {
        // No type declarations ship for this SDK-injected global — narrow assertion is the
        // only option here, see comment above for why we can't import the SDK's own types/fn.
        const buildOrigin = (window as unknown as {Progressive?: {buildOrigin?: string}}).Progressive?.buildOrigin
        if (buildOrigin) return `${buildOrigin}${path}`
    }

    return `/${path}`
}

