import React from 'react';
import { Global, css } from '@emotion/react';

/**
 * @font-face declarations for the self-hosted Futura Round faces.
 *
 * This is the only thing the font needs. `foundation/fonts.ts` already lists
 * 'Futura Round' as first preference in both FONT_REGULAR and FONT_MEDIUM, and every layer
 * below it — zimmTokens' --zimm-font-family-*, the 22 textStyles, every component recipe —
 * already resolves through that stack. Declaring the faces makes the name resolvable; nothing
 * else in the styling chain changes.
 *
 * Only two faces exist because only two are used: all 22 textStyles resolve to fontWeight
 * 400 or 500, and fonts.body === fonts.heading, so there is no third stack to serve.
 *
 * Injected with a raw Emotion <Global> rather than Chakra's styles.global, for the same
 * reason zimmTokensGlobal.tsx documents: Chakra's style processor mangles quoted font-family
 * values, collapsing a stack like "'Futura Round', 'Century Gothic', sans-serif" to a single
 * family. Rendered in the app by _app-config/index.tsx AND in Storybook by
 * .storybook/preview.tsx, so type resolves identically in isolation and in the app — one
 * shared definition so the two mount points cannot drift.
 */

// Populated at SSR module-init time via a webpackIgnore'd dynamic import so webpack never
// traces the SSR-only module chain (pwa-kit-runtime → cosmiconfig → fs) into the browser or
// Storybook bundle. Real PWA Kit builds define a WEBPACK_TARGET constant that lets that chain
// be dead-code-eliminated from a static import, but .storybook/main.js does not define it, so
// a plain top-level import would drag cosmiconfig/fs into the Storybook bundle and fail to
// resolve.
let getAssetUrlSsr: ((path: string) => string) | undefined;

if (typeof window === 'undefined') {
  void import(/* webpackIgnore: true */ '@salesforce/pwa-kit-react-sdk/ssr/universal/utils')
    .then((m) => {
      getAssetUrlSsr = m.getAssetUrl;
    })
    .catch(() => {});
}

/**
 * Resolves the bundle-prefixed URL for a font file across all three environments.
 *
 *   SSR       — getAssetUrl() from the dynamically imported SDK module above.
 *   Browser   — window.Progressive.buildOrigin, the same value getAssetUrl reads client-side,
 *               set by the PWA Kit client runtime before hydration. Read directly rather than
 *               importing the SDK, for the bundling reason above.
 *   Storybook — neither exists, so the bare /static path is used. That resolves because
 *               .storybook/main.js maps overrides/app/static to /static via staticDirs.
 */
const fontUrl = (filename: string): string => {
  const path = `static/fonts/${filename}`;

  if (getAssetUrlSsr) {
    try {
      return getAssetUrlSsr(path);
    } catch {
      /* fall through to the browser/Storybook paths below */
    }
  }

  if (typeof window !== 'undefined') {
    // No type declarations ship for this SDK-injected global, so a narrow assertion is the
    // only option — see the note above on why the SDK's own helper cannot be imported here.
    const buildOrigin = (window as unknown as { Progressive?: { buildOrigin?: string } }).Progressive?.buildOrigin;
    if (buildOrigin) return `${buildOrigin}${path}`;
  }

  return `/${path}`;
};

const fontFaceCss = css`
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Regular.woff2')}') format('woff2');
    font-weight: 400;
    font-style: normal;
    font-display: swap;
  }
