import React from 'react';
import { Global, css } from '@emotion/react';
import { bundleBasePath, getEnvBasePath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';

/**
 * @font-face declarations for the self-hosted Futura Round faces.
 *
 * This is the only thing the font needs. `foundation/fonts.ts` already lists 'Futura Round'
 * as first preference in both FONT_REGULAR and FONT_MEDIUM, and every layer below it —
 * zimmTokens' --zimm-font-family-*, the 22 textStyles, every component recipe — already
 * resolves through that stack. Declaring the faces makes the name resolvable; nothing else in
 * the styling chain changes.
 *
 * Only two faces exist because only two are used: all 22 textStyles resolve to fontWeight 400
 * or 500, and fonts.body === fonts.heading, so there is no third stack to serve.
 *
 * Injected with a raw Emotion <Global> rather than Chakra's styles.global, for the same reason
 * zimmTokensGlobal.tsx documents: Chakra's style processor mangles quoted font-family values,
 * collapsing a stack like "'Futura Round', 'Century Gothic', sans-serif" to a single family.
 * Rendered in the app by _app-config/index.tsx AND in Storybook by .storybook/preview.tsx, so
 * type resolves identically in isolation and in the app — one shared definition so the two
 * mount points cannot drift.
 */

/**
 * Bundle-prefixed asset root, resolved synchronously.
 *
 * This deliberately reimplements the two lines of `getAssetUrl` rather than importing it.
 * That helper lives in `@salesforce/pwa-kit-react-sdk/ssr/universal/utils`, which also pulls
 * in `ssr-config` (cosmiconfig → fs) — fine on the server, but it would land in the browser
 * and Storybook bundles. Importing it lazily to dodge that is worse: this module's css`` is
 * evaluated at module-init, so an async import can never populate in time and every URL
 * silently loses its bundle prefix, 404s, and the browser falls back to the system font.
 *
 * `ssr-namespace-paths` is dependency-free, so it imports statically and resolves in one tick.
 *
 *   SSR      → `${getEnvBasePath()}${bundleBasePath}/${BUNDLE_ID}/`  e.g. /mobify/bundle/development/
 *   Browser  → window.Progressive.buildOrigin, set by the PWA Kit client runtime pre-hydration
 *   Storybook→ neither applies, so the bare /static path is used; .storybook/main.js maps
 *              overrides/app/static to /static via staticDirs, so it resolves there too.
 */
const assetRoot = (): string => {
  if (typeof window !== 'undefined') {
    // No type declarations ship for this SDK-injected global, so a narrow assertion is the
    // only option. Storybook has no Progressive global and falls through to '/'.
    const buildOrigin = (window as unknown as { Progressive?: { buildOrigin?: string } }).Progressive?.buildOrigin;
    return buildOrigin ?? '/';
  }
  return `${getEnvBasePath()}${bundleBasePath}/${process.env.BUNDLE_ID || 'development'}/`;
};

const fontUrl = (filename: string): string => `${assetRoot()}static/fonts/${filename}`;

const fontFaceCss = css`
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Regular.woff2')}') format('woff2');
    font-weight: 400;
    font-style: normal;
    font-display: swap;
  }
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Medium.woff2')}') format('woff2');
    font-weight: 500;
    font-style: normal;
    font-display: swap;
  }
`;

/** Declares the self-hosted Futura Round faces. Render once, high in the tree. */
export function ZimmFontFace(): React.ReactElement {
  return <Global styles={fontFaceCss} />;
}

/**
 * Ambient module declarations for @salesforce/retail-react-app.
 *
 * This package ships without TypeScript types. We declare the modules we
 * import in overrides/ with real types where we know the shape, and fall
 * back to an untyped catch-all for everything else.
 *
 * Add specific declarations here as more subpaths are consumed in overrides/.
 */

declare module '@salesforce/retail-react-app/app/theme' {
  import type { ChakraTheme } from '@chakra-ui/react';
  const theme: ChakraTheme;
  export default theme;
}

// Matches the pinned react-router-dom 5.3.4 (see package.json) — the package ships
// without its own types and no @types/react-router-dom is installed, so this mirrors
// that version's real shapes (history's Location/LocationDescriptor, match) rather
// than a generic approximation.
declare module 'react-router-dom' {
  import type React from 'react';

  interface Location<TState = unknown> {
    pathname: string;
    search: string;
    hash: string;
    state: TState;
    key?: string;
  }
  export function useLocation<TState = unknown>(): Location<TState>;

  // Every declared param is optional — a route pattern doesn't guarantee a segment
  // was actually present in the matched URL. Default is `{}` in the real react-router
  // types (so an unparameterised useParams()'s properties correctly fail to resolve);
  // `NonNullable<unknown>` is the eslint-approved equivalent — our ban-types rule
  // rejects a literal `{}`, and `Record<string, never>` was tried and rejected in
  // review: it types every property as `never`, which is assignable to anything and
  // so silently passes property access that should be a compile error.
  export function useParams<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>>(): TParams;

  type To<TState = unknown> = string | { pathname?: string; search?: string; hash?: string; state?: TState };

  interface LinkProps<TState = unknown> extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
    to: To<TState>;
    replace?: boolean;
  }
  export const Link: React.ForwardRefExoticComponent<LinkProps & React.RefAttributes<HTMLAnchorElement>>;

  interface match<TParams extends { [K in keyof TParams]?: string } = NonNullable<unknown>> {
    params: TParams;
    isExact: boolean;
    path: string;
    url: string;
  }

  interface NavLinkProps extends LinkProps {
    exact?: boolean;
    activeClassName?: string;
    activeStyle?: React.CSSProperties;
    isActive?: (match: match | null, location: Location) => boolean;
  }
  export const NavLink: React.ForwardRefExoticComponent<NavLinkProps & React.RefAttributes<HTMLAnchorElement>>;
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/utils' {
  export function getAssetUrl(path: string): string;
}

declare module '@salesforce/pwa-kit-runtime/utils/ssr-config' {
  export function getConfig(): { app: Record<string, unknown> };
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks' {
  type ServerResponse = {
    set: (name: string, value: string) => void;
    status: (code: number) => ServerResponse;
  };
  export function useServerContext(): {
    req?: any;
    res?: ServerResponse;
  };
  export function useCorrelationId(): { correlationId: string };
}

declare module '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths' {
  export const getEnvBasePath: () => string;
  export const slasPrivateProxyPath: string;
  export const bundleBasePath: string;
}

declare module '@salesforce/pwa-kit-runtime/utils/logger-factory' {
  const createLogger: (opts: { packageName: string }) => any;
  export default createLogger;
}

declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query' {
  export function withReactQuery(Component: any, options?: any): any;
}

declare module '@salesforce/pwa-kit-react-sdk/utils/url' {
  export function getAppOrigin(): string;
}

declare module '@loadable/component' {
  const loadable: (fn: () => Promise<any>, opts?: any) => any;
  export default loadable;
}

// Static asset imports (webpack url-loader / asset modules)
declare module '*.svg' {
  const src: string;
  export default src;
}

// Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
declare module '@salesforce/retail-react-app/*';

// @vitejs/plugin-react uses package exports only (no root index.d.ts), which
// TypeScript 4.9 with moduleResolution:node cannot resolve. Minimal shim — the
// actual Plugin return type depends on vite types that are equally unreachable
// from TS 4.9. Once the project upgrades to TS 5+ this declaration can be removed.
declare module '@vitejs/plugin-react' {
  interface Options {
    include?: string | RegExp | Array<string | RegExp>;
    exclude?: string | RegExp | Array<string | RegExp>;
    jsxImportSource?: string;
  }
  // Return typed as any: Plugin from vite is not resolvable under moduleResolution:node.
  function react(options?: Options): any;
  export default react;
}

const path = require('path');

/** @type { import('@storybook/react-webpack5').StorybookConfig } */
const config = {
  stories: ['../overrides/**/*.stories.@(js|jsx|ts|tsx|mdx)'],
  // Serve overrides/app/static/ so self-hosted assets resolve in Storybook the same way
  // getAssetUrl resolves them in the app. Mapped to /static (rather than the bare directory)
  // so the fallback path in overrides/app/theme/fontFace.tsx is a real URL here instead of a
  // silent 404 — without this, Storybook renders the fallback font while the app renders
  // Futura Round, and no visual comparison made in Storybook can be trusted.
  staticDirs: [{ from: '../overrides/app/static', to: '/static' }],
  addons: [
    '@storybook/addon-webpack5-compiler-babel',
    '@storybook/addon-links',
    '@storybook/addon-docs',
    '@storybook/addon-a11y',
  ],
  framework: {
    name: '@storybook/react-webpack5',
    options: {},
  },
  webpackFinal: async (webpackConfig) => {
    // Resolve PWA Kit package aliases so imports from
    // '@salesforce/retail-react-app/...' resolve correctly.
    webpackConfig.resolve.alias = {
      ...webpackConfig.resolve.alias,
      // Project path aliases — keep in sync with babel.config.js, tsconfig.json
      // (jest.config.js's aliases are separate — for @salesforce/pwa-kit-dev internals only)
      '~': path.resolve(__dirname, '..'),
      app: path.resolve(__dirname, '../overrides/app'),
      '@salesforce/retail-react-app': path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      '@salesforce/pwa-kit-react-sdk': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-react-sdk'),
      '@salesforce/pwa-kit-runtime': path.resolve(__dirname, '../node_modules/@salesforce/pwa-kit-runtime'),
      '@salesforce/commerce-sdk-react': path.resolve(__dirname, '../node_modules/@salesforce/commerce-sdk-react'),
    };

    // Allow Storybook to process JSX inside @salesforce/retail-react-app,
    // which ships un-compiled .jsx source files.
    webpackConfig.module.rules.push({
      test: /\.(js|jsx)$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      use: { loader: 'babel-loader' },
    });

    // Storybook adds a default asset/resource rule that catches all SVGs — remove it
    // so our scoped rules below can take full control.
    webpackConfig.module.rules = webpackConfig.module.rules.filter(
      (rule) => !(rule?.test instanceof RegExp && rule.test.test('.svg')),
    );

    // Mirror the PWA Kit browser build: SFCC SVGs are sprite-loaded server-side only,
    // so the browser (and Storybook) should ignore those imports entirely.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      include: path.resolve(__dirname, '../node_modules/@salesforce/retail-react-app'),
      loader: 'ignore-loader',
    });

    // Treat project SVGs as file assets.
    webpackConfig.module.rules.push({
      test: /\.svg$/,
      exclude: /node_modules/,
      type: 'asset/resource',
    });

    return webpackConfig;
  },
};

module.exports = config;

import React from 'react';
import type { Preview, Decorator } from '@storybook/react-webpack5';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import theme from '../overrides/app/theme';
import { ZimmTokensGlobal } from '../overrides/app/theme/zimmTokensGlobal';
import { ZimmFontFace } from '../overrides/app/theme/fontFace';

// ZimmTokensGlobal injects the --zimm-* :root custom properties, mirroring what
// _app-config does in the app. Without it, the .zimm-* global classes and the
// var(--zimm-*) component overrides (button/header/listMenu) render unresolved in
// Storybook. Same shared source as the app, so the two cannot drift.
//
// ZimmFontFace declares the self-hosted Futura Round faces, likewise mirroring
// _app-config. Without it Storybook renders the fallback stack while the app renders
// Futura Round — the fallback measures ~13% wider, so any visual comparison made in
// Storybook would not match the app or Figma. Font files are served here by the
// staticDirs mapping in .storybook/main.js.
const withChakra: Decorator = (Story) => (
  <ChakraProvider theme={theme}>
    <ZimmFontFace />
    <ZimmTokensGlobal />
    <Story />
  </ChakraProvider>
);

const withIntl: Decorator = (Story) => (
  <IntlProvider locale="en-AU" defaultLocale="en-AU">
    <Story />
  </IntlProvider>
);

const preview: Preview = {
  parameters: {
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /date$/i,
      },
    },
    layout: 'centered',
    a11y: {
      // 'error' causes a11y violations to fail test-storybook --ci runs
      test: 'error',
      // Chakra UI injects toast region containers (role="region") at the root
      // without an accessible name — a known upstream limitation. Exclude them
      // from all a11y checks since they are framework-level, not component output.
      context: {
        exclude: [
          '#chakra-toast-manager-top',
          '#chakra-toast-manager-top-right',
          '#chakra-toast-manager-top-left',
          '#chakra-toast-manager-bottom',
          '#chakra-toast-manager-bottom-right',
          '#chakra-toast-manager-bottom-left',
        ],
      },
    },
  },
  decorators: [withChakra, withIntl],
};

export default preview;

