══════ 3. Jersey's extractTsProps (full) ══════
   * When `preferredTypeName` is given (e.g. "FooterProps"), only that block's props
   * are returned if it exists — prevents sub-component internal Props types in the
   * same file from leaking into the registry row for the public component.
   * Falls back to collecting all *Props blocks when the preferred name isn't found.
   */
  function extractTsProps(content, preferredTypeName = null) {
    const re = /(?:type|interface)\s+(\w*Props)\s*(?:=\s*)?\{([\s\S]*?)\n\}/g
    const allBlocks = []
    let blockMatch
    while ((blockMatch = re.exec(content)) !== null) {
      const typeName = blockMatch[1]
      const body = blockMatch[2]
      const blockProps = []
      const blockSeen = new Set()
      const lineRe = /^\s{2,}(\w+)(\??):\s*(.+?)\s*[;,]?\s*$/gm
      let m
      while ((m = lineRe.exec(body)) !== null) {
        const name = m[1]
        if (blockSeen.has(name) || name === 'children') continue
        blockSeen.add(name)
        const optional = m[2] === '?'
        const type = m[3].trim()
        blockProps.push(`${name}${optional ? '?' : ''}: ${type}`)
      }
      allBlocks.push({typeName, props: blockProps})
    }

    if (preferredTypeName) {
      const preferred = allBlocks.find(({typeName}) => typeName === preferredTypeName)
      if (preferred) return preferred.props
    }

    // Fallback: merge all blocks, deduplicating by prop name (first occurrence wins).
    const seen = new Set()
    const props = []
    for (const {props: blockProps} of allBlocks) {
      for (const p of blockProps) {
        const name = p.split(/[?:]/)[0]
        if (!seen.has(name)) {
          seen.add(name)
          props.push(p)
        }
      }
    }
    return props
  }
  /**
   * Extract named exports from a utility file.

