cat > "$CLAUDE_JOB_DIR/tmp/ackfix.mjs" <<'EOF'
import { chromium } from '/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright-core/index.mjs';
const b = await chromium.launch();
const p = await b.newPage({ viewport:{width:1440,height:900} });
await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded' });
await p.waitForSelector('footer', { timeout:60000 });
await p.waitForTimeout(2500);

const r = await p.evaluate(() => {
  const f = document.querySelector('footer');
  const ack = [...f.querySelectorAll('ul li a')].find(a => /acknowledgement/i.test(a.textContent||''));
  const cs = getComputedStyle(ack);
  // measure arbitrary strings in the anchor's exact typography
  const probe = document.createElement('span');
  Object.assign(probe.style, {
    position:'absolute', visibility:'hidden', whiteSpace:'nowrap',
    fontFamily:cs.fontFamily, fontSize:cs.fontSize, fontWeight:cs.fontWeight,
    letterSpacing:cs.letterSpacing, textTransform:cs.textTransform,
  });
  document.body.appendChild(probe);
  const w = s => { probe.textContent = s; return +probe.getBoundingClientRect().width.toFixed(1); };

  const parts = {
    'ACKNOWLEDGEMENT'      : w('Acknowledgement'),
    'ACKNOWLEDGEMENT OF'   : w('Acknowledgement of'),
    'OF COUNTRY'           : w('of Country'),
    'COUNTRY'              : w('Country'),
    'FULL STRING'          : w('Acknowledgement of Country'),
  };
  // every other nav label, single-line width
  const labels = {};
  f.querySelectorAll('ul li a').forEach(a => {
    const t = (a.textContent||'').trim();
    if (!/acknowledgement/i.test(t)) labels[t] = w(t);
  });
  document.body.removeChild(probe);

  const rect = ack.getBoundingClientRect();
  return { parts, labels,
    ackRendered: `${rect.width.toFixed(1)} x ${rect.height.toFixed(1)}`,
    ackMaxWidth: getComputedStyle(ack.parentElement.parentElement.parentElement).maxWidth,
    colMaxWidth: cs.maxWidth, font: cs.fontFamily.split(',')[0], fs: cs.fontSize, ls: cs.letterSpacing };
});
console.log('font :', r.font, r.fs, 'ls', r.ls);
console.log('ACK renders at:', r.ackRendered, '\n');
console.log('  segment widths (real font):');
for (const [k,v] of Object.entries(r.parts)) console.log(`    ${k.padEnd(22)} ${v}px`);
console.log('\n  other nav labels:');
Object.entries(r.labels).sort((a,b)=>b[1]-a[1]).forEach(([k,v])=>console.log(`    ${k.padEnd(26)} ${v}px`));
await b.close();
EOF
node "$CLAUDE_JOB_DIR/tmp/ackfix.mjs"

