  await p.goto('http://localhost:3000/', { waitUntil:'domcontentloaded' });
  await p.waitForSelector('footer', { timeout:60000 });
  await p.waitForTimeout(1800);
  const r = await p.evaluate(() => {
    const f = document.querySelector('footer');
    const ack = [...f.querySelectorAll('ul li a')].find(a => /acknowledgement/i.test(a.textContent||''));
    // derive the visual line break by measuring client rects of the text node
    const range = document.createRange();
    range.selectNodeContents(ack);
    const rects = [...range.getClientRects()].filter(r => r.width > 1);
    const rect = ack.getBoundingClientRect();
    // which labels wrap?
    const wrapped = [];
    f.querySelectorAll('ul li a').forEach(a => { if (a.getBoundingClientRect().height > 26) wrapped.push((a.textContent||'').trim().slice(0,24)); });
    return { w:+rect.width.toFixed(1), h:+rect.height.toFixed(1), lines:rects.length,
             lineWidths: rects.map(r=>+r.width.toFixed(1)), wrapped };
  });
  console.log(`${String(vw).padStart(4)}px  ACK ${r.w}x${r.h}  lines=${r.lines}  lineWidths=[${r.lineWidths}]`);
  console.log(`        wrapped: ${r.wrapped.join(' | ') || 'none'}`);
  await p.close();
}
await b.close();
EOF
