const wrap = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);

describe('JERSEY TAKE #4 — zimmNavItem unsafe-href fallback', () => {
  test('omitted / javascript: / data: / protocol-relative all render as <button> with no href', async () => {
    const { container } = wrap(
      <div>
        <ZimmNavItem label="Omitted href" />
        <ZimmNavItem label="javascript: href" href="javascript:void(0)" />
        <ZimmNavItem label="data: href" href="data:text/html,xss" />
        <ZimmNavItem label="Protocol-relative href" href="//example.com" />
      </div>,
