    return { x:+(r.left-q.left).toFixed(1), y:+(r.top-q.top).toFixed(1), w:+r.width.toFixed(1), h:+r.height.toFixed(1) }; };

  const main=f.firstElementChild, contentRow=main.children[0], logoArea=main.children[1], bottomBar=f.lastElementChild;
  const subscribe=contentRow.children[0], links=contentRow.children[1];
  const uls=[...links.querySelectorAll('ul')].filter(u=>u.querySelectorAll('li').length>2);
  const cols=uls.map(u=>u.closest('div'));
  const subP=[...subscribe.querySelectorAll('p')];
  const field=subscribe.querySelector('div:has(input)') || subscribe.querySelector('input')?.closest('div');
  const logo=f.querySelector('svg[aria-label="Zimmermann"]');
  const locale=f.querySelector('button[aria-label="Change locale"]');
  const iconRow=[...links.querySelectorAll('li')].find(li=>li.querySelectorAll('svg').length>=2);

  const out={
    footer:box(f), content:box(contentRow), subscribe:box(subscribe), siteMap:box(links),
    subHeading: rel(subP[0], subscribe), subBody: rel(subP[1], subscribe),
    field: field? rel(field, subscribe):null,
    logoArea:box(logoArea), logo:box(logo), legal:box(bottomBar), locale:box(locale),
    columns: cols.map(c=>({ name:c.querySelector('p,h2,h3')?.textContent.trim().slice(0,8),
