import { describe, test, expect, beforeEach, afterEach, vi } from 'vitest';

/**
 * assetRoot resolved the wrong path once already: every @font-face URL lost its bundle
 * prefix, the files came back as HTML, and only inspecting the network in a browser found
 * it. These pin the three branches so the same class of break fails at the gate instead.
 *
 * The module builds `fontFaceCss` at import time, so each case needs a fresh module
 * registry with the intended globals already in place — hence resetModules rather than
 * calling assetRoot, which is private by design.
 */

const BUNDLE_PATH = '/mobify/bundle';

vi.mock('@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths', () => ({
  getEnvBasePath: () => '',
  bundleBasePath: BUNDLE_PATH,
  slasPrivateProxyPath: '',
}));

/** Renders ZimmFontFace and returns the @font-face src URLs Emotion was handed. */
const srcUrls = async (): Promise<string[]> => {
  vi.resetModules();
  const { ZimmFontFace } = await import('./fontFace');
  const { renderToStaticMarkup } = await import('react-dom/server');
  const { CacheProvider } = await import('@emotion/react');
  const createCache = (await import('@emotion/cache')).default;
  const React = (await import('react')).default;
  const cache = createCache({ key: 'zfp' });
  renderToStaticMarkup(React.createElement(CacheProvider, { value: cache }, React.createElement(ZimmFontFace)));
  const css = Object.values(cache.inserted).join('');
  return [...css.matchAll(/url\('([^']+)'\)/g)].map((m) => m[1]);
};

const originalWindow = globalThis.window;

afterEach(() => {
  if (originalWindow === undefined) delete (globalThis as { window?: unknown }).window;
  vi.unstubAllEnvs();
});

describe('ZimmFontFace asset resolution', () => {
  beforeEach(() => {
    vi.stubEnv('BUNDLE_ID', 'development');
  });

  test('browser: uses window.Progressive.buildOrigin', async () => {
    (globalThis as { window?: unknown }).window = { Progressive: { buildOrigin: 'https://cdn.example/' } };
    const urls = await srcUrls();
    expect(urls).toHaveLength(2);
    urls.forEach((u) => expect(u).toMatch(/^https:\/\/cdn\.example\/static\/fonts\//));
  });

  test('browser without the Progressive global: falls back to / (the Storybook case)', async () => {
    (globalThis as { window?: unknown }).window = {};
    const urls = await srcUrls();
    urls.forEach((u) => expect(u).toMatch(/^\/static\/fonts\//));
  });

  test('declares exactly two faces — Regular 400 and Medium 500', async () => {
    (globalThis as { window?: unknown }).window = {};
    const urls = await srcUrls();
    expect(urls).toHaveLength(2);
    expect(urls.some((u) => /FuturaRound-Regular\.woff2$/.test(u))).toBe(true);
    expect(urls.some((u) => /FuturaRound-Medium\.woff2$/.test(u))).toBe(true);
  });

  test('every URL ends in .woff2 under static/fonts — never a bare filename', async () => {
    (globalThis as { window?: unknown }).window = {};
    const urls = await srcUrls();
    urls.forEach((u) => expect(u).toMatch(/static\/fonts\/[A-Za-z-]+\.woff2$/));
  });
});
