const F = require(process.env.CLAUDE_JOB_DIR + '/tmp/foundation.cjs');

// value (normalised) -> [token paths]
const index = new Map();
const add = (val, path) => {
  const k = norm(val);
  if (k === null) return;
  if (!index.has(k)) index.set(k, []);
  index.get(k).push(path);
};

function norm(v) {
  if (typeof v === 'number') return `n:${v}`;
  if (typeof v !== 'string') return null;
  const s = v.trim().toLowerCase();
  if (s.startsWith('var(')) return null;                  // reference, not a value
  let m;
  if ((m = s.match(/^(-?[\d.]+)px$/)))  return `len:${(+m[1]).toFixed(4)}`;
  if ((m = s.match(/^(-?[\d.]+)rem$/))) return `len:${(+m[1]*16).toFixed(4)}`;
  if ((m = s.match(/^(-?[\d.]+)em$/)))  return `len:${(+m[1]*16).toFixed(4)}`;

