const R='/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/';
const files=fs.readFileSync(process.env.CLAUDE_JOB_DIR+'/tmp/prfiles.txt','utf8').trim().split('\n');
const LIT=/(-?[\d.]+(?:px|rem|em)|#[0-9a-fA-F]{3,8}|rgba?\([^)]*\))/g;
const rows=[];
for(const f of files){
  const p=R+f; if(!fs.existsSync(p))continue;
  const isStory=/\.stories\./.test(f), isTest=/\.test\./.test(f);
  fs.readFileSync(p,'utf8').split('\n').forEach((l,i)=>{
    if(/^\s*(\/\/|\*|\/\*)/.test(l))return;            // comment line
    const code=l.replace(/\/\/.*$/,'').replace(/var\(--[a-z0-9-]+\)/gi,'VAR');
    let m; LIT.lastIndex=0;
    while((m=LIT.exec(code))){
      const raw=m[1], k=norm(raw);
      rows.push({f,ln:i+1,raw,k,tok:k&&index.has(k)?index.get(k):null,isStory,isTest,src:l.trim().slice(0,72)});
    }
  });
}
const prod=rows.filter(r=>!r.isStory&&!r.isTest);
const matched=prod.filter(r=>r.tok), unmatched=prod.filter(r=>!r.tok);
console.log(`scope: ${files.length} files · ${rows.length} literals (${prod.length} in production paths, ${rows.length-prod.length} in stories/tests)\n`);
console.log(`── 2a. literal that EQUALS a registered token value → candidate mirror (${matched.length}) ──`);
const byTok={}; matched.forEach(r=>{const key=r.tok.join(',');(byTok[key]=byTok[key]||[]).push(r);});
Object.entries(byTok).sort((a,b)=>b[1].length-a[1].length).forEach(([t,rs])=>{
  console.log(`  ${rs[0].raw.padEnd(22)} == ${t}`);
  rs.forEach(r=>console.log(`      ${r.f.replace('overrides/app/','')}:${r.ln}  ${r.src}`));
});
console.log(`\n── 2b. literal with NO token equivalent → gap or provisional (${unmatched.length}) ──`);
const byFile={}; unmatched.forEach(r=>{(byFile[r.f]=byFile[r.f]||[]).push(r);});
Object.entries(byFile).forEach(([f,rs])=>{
  console.log(`  ${f.replace('overrides/app/','')}`);
  rs.forEach(r=>console.log(`      :${r.ln}  ${r.raw.padEnd(20)} ${r.src}`));
});
EOF
