  166| // Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
  167| type PendingSignup = { email: string; firstName: string; lastName: string };
  168|     14	
  169| type SubscribeSectionProps = { heading: string; body: string; initialSubscribed?: boolean; privacyPolicyHref: string };
  170|     16	
  171| const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
  172| const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';
  173|     19	
  174| const SubscribeSection = ({ heading, body, initialSubscribed = false, privacyPolicyHref }: SubscribeSectionProps) => {
  175| // Map the Storybook-only `initialSubscribed` flag to the success state.
  176| // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
  177| const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
  178| // Ref, not state: nothing renders from it, so a re-render on capture would be wasted.
  179| // The footer input unmounts once submitState leaves 'idle', so the email must be
  180| // captured here at step 1 or it is unrecoverable at step 2.
  181| const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
  182| const [modalOpen, setModalOpen] = useState(false);
  183| const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
  184|     30	
  185| const handleEmailSubmit = (email: string) => {
  186| pendingSignupRef.current.email = email;
  187| setModalOpen(true);
  188| };
  189|     35	
  190| const handleModalSubmit = (firstName: string, lastName: string) => {
  191| pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
  192| // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
  193| // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
  194| // 'unavailable' is shown until the integration is live; never show false success.
  195| setModalOpen(false);
  196| setSubmitState('unavailable');
  197| // Nothing was sent, so nothing needs retaining — the record holds customer PII and there
  198| // is no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it
  199| // just moves to after a confirmed response. React memory only, never storage, never logged.
  200| pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  201| };
  202|     48	
  203| return (
  204| <div>
  205| <chakra.p __css={styles.subscribeHeading}>{heading}</chakra.p>
  206| <chakra.p __css={styles.subscribeBody}>{body}</chakra.p>
  207| <div aria-live="polite">
  208| {submitState === 'idle' && (
  209| <ZimmInputAction
  210| label="Email"
  211| type="email"
  212| name="footer-email"
  213| icon="chevron-right"
  214| buttonLabel="Subscribe"
  215| inverse
  216| onSubmit={handleEmailSubmit}
  217| />
  218| )}
  219| {submitState === 'success' && <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_SUCCESS_MESSAGE}</chakra.p>}
  220| {(submitState === 'unavailable' || submitState === 'error') && (
  221| <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_UNAVAILABLE_MESSAGE}</chakra.p>
  222| )}
  223| </div>
  224|     70	
  225| <SubscribeModal
  226| isOpen={modalOpen}
  227| onClose={() => setModalOpen(false)}
  228| onSubmit={handleModalSubmit}
  229| privacyPolicyHref={privacyPolicyHref}
  230| />
  231| </div>
  232| );
  233| };
