import pathlib
p=pathlib.Path('overrides/app/components/footer/index.tsx'); s=p.read_text()

# 1. SubscribeSection props
old="type SubscribeSectionProps = { heading: string; body: string; initialSubscribed?: boolean; privacyPolicyHref: string };"
new="""type SubscribeSectionProps = {
  heading: string;
  body: string;
  initialSubscribed?: boolean;
  privacyPolicyHref: string;
  enableNameCapture?: boolean;
};"""
assert old in s; s=s.replace(old,new,1)

# 2. destructure with default off
old="const SubscribeSection = ({ heading, body, initialSubscribed = false, privacyPolicyHref }: SubscribeSectionProps) => {"
new="const SubscribeSection = ({\n  heading,\n  body,\n  initialSubscribed = false,\n  privacyPolicyHref,\n  enableNameCapture = false,\n}: SubscribeSectionProps) => {"
assert old in s; s=s.replace(old,new,1)

# 3. gate the transition
old="""  const handleEmailSubmit = (email: string) => {
    pendingSignupRef.current.email = email;
    setModalOpen(true);
  };"""
new="""  const handleEmailSubmit = (email: string) => {
    pendingSignupRef.current.email = email;
    if (enableNameCapture) {
      setModalOpen(true);
      return;
    }
    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
    // story. The name-capture modal is HPC-035/HPC-037 (both confirmed in .docs/prd/homepage.md
    // §6) but has no Figma node — every one of its nine theme parts is undesigned, unlike the 27
    // Figma-referenced parts around it. So it does not ship enabled: submitting a valid email
    // goes straight to the placeholder message. Flip this prop on once Kiera supplies the design
    // and HPC-035 is scheduled; the modal and its coverage are already built and tested.
    setSubmitState('unavailable');
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };"""
assert old in s; s=s.replace(old,new,1)

# 4. only render the modal when enabled
old="""      <SubscribeModal
        isOpen={modalOpen}
        onClose={() => setModalOpen(false)}
        onSubmit={handleModalSubmit}
        privacyPolicyHref={privacyPolicyHref}
      />"""
new="""      {enableNameCapture && (
        <SubscribeModal
