// Mirror the WHATWG URL parser: trim leading/trailing C0+space, then strip tab/LF/CR anywhere.
const CTL = '[' + C(0) + '-' + C(32) + ']';
const TRIM = new RegExp('^' + CTL + '+|' + CTL + '+$', 'g');
const STRIP = new RegExp('[' + TAB + LF + CR + ']', 'g');
const normalise = (h) => h.replace(TRIM, '').replace(STRIP, '');

const OLD = /^(https?:|tel:|mailto:|#|\/(?!\/))/i;
const NEW = /^(https?:|tel:|mailto:|#|\/(?![\/\\]))/i;
const cases = [
  ['/womens', true], ['https://zimmermann.com', true], ['http://x.com', true],
  ['tel:+61280808080', true], ['mailto:a@b.com', true], ['#top', true],
  ['/ /evil.com', true],
  ['//example.com', false], ['/\\example.com', false], ['/\\/evil.com', false],
  ['/' + TAB + '/evil.com', false], ['/' + LF + '/evil.com', false], ['/' + CR + '/evil.com', false],
  [TAB + '//evil.com', false], [' //evil.com', false], ['\\\\example.com', false],
  ['javascript:x', false], ['JavaScript:x', false], ['data:text/html,x', false],
  ['vbscript:x', false], ['', false],
];
let bad = 0;
console.log('  case                        old      new      want     resolves to');
for (const [h, want] of cases) {
  const o = OLD.test(h), n = h ? NEW.test(normalise(h)) : false;
  let r = ''; try { r = new URL(h, 'https://www.zimmermann.com').href } catch { r = '(invalid)' }
  const ok = n === want; if (!ok) bad++;
  console.log('  ' + JSON.stringify(h).padEnd(27) + String(o).padEnd(9) + String(n).padEnd(9) +
    String(want).padEnd(9) + r.slice(0, 34) + (ok ? '' : '  <-- WRONG'));
}
console.log('  mismatches: ' + bad);
'''
pathlib.Path(os.environ['CLAUDE_JOB_DIR']+'/tmp/hreftest.mjs').write_text(js)
print("  written")
