  );
};

describe('probe: focus containment', () => {
  test('Tab from <body> (after clicking non-focusable prose) escapes the dialog', async () => {
    const user = userEvent.setup();
    render(<Harness />);
    await user.click(screen.getByTestId('prose'));
    expect(document.activeElement).toBe(document.body); // focus is outside the focusable set
    await user.tab();
