new = """  if (preferredTypeName) {
    const preferred = allBlocks.find(({typeName}) => typeName === preferredTypeName)
    if (preferred) return preferred.props

    // The preferred type can also be a *union alias* — `type ZimmButtonProps = ZimmLabelButtonProps
    // | ZimmIconButtonProps` — which the block regex above cannot match, having no object-literal
    // body. Left to fall through, the merge-everything fallback flattens every variant into one
    // row and presents mutually-exclusive props as co-required: ZimmButton's row claimed both
    // `label: string` and `icon: ZimmIconType`, a combination the type forbids.
    const alias = new RegExp(`type\\\\s+${preferredTypeName}\\\\s*=\\\\s*([^;{]+);`).exec(content)
    if (alias && alias[1].includes('|')) {
      const memberNames = alias[1].split('|').map((s) => s.trim())
      const members = memberNames
        .map((name) => allBlocks.find(({typeName}) => typeName === name))
        .filter(Boolean)

      // Members declared in another file can't be resolved from this content. Surface the union
      // expression rather than falling through to the merge that misreports it.
      if (!members.length) return [memberNames.join(' | ')]

      // A prop carried by every member is unconditionally present; one carried by only some is
      // conditional on which variant you picked, which is precisely what `?` means at the union.
      const nameOf = (prop) => prop.split(/[?:]/)[0]
      const memberCount = new Map()
      for (const {props: memberProps} of members) {
        for (const name of new Set(memberProps.map(nameOf))) {
          memberCount.set(name, (memberCount.get(name) ?? 0) + 1)
        }
      }

