assert src.count(old_body) == 1
src = src.replace(old_body, new_body)

old_push = "    allBlocks.push({typeName, props: blockProps})"
new_push = "    allBlocks.push({typeName, prefix, props: blockProps})"
assert src.count(old_push) == 1
