old_pref = """  if (preferredTypeName) {
    const preferred = allBlocks.find(({typeName}) => typeName === preferredTypeName)
    if (preferred) return preferred.props
  }
"""
new_pref = """  if (preferredTypeName) {
    const preferred = allBlocks.find(({typeName}) => typeName === preferredTypeName)
    if (preferred) return preferred.props

    // The preferred type can also be a *union alias* — `type ZimmButtonProps = ZimmLabelButtonProps
    // | ZimmIconButtonProps` — which the block regex above cannot match, having no object-literal
    // body. Left to fall through, the merge-everything fallback flattens every variant into one row
    // and presents mutually-exclusive props as co-required: ZimmButton's row claimed both
    // `label: string` and a required `icon: ZimmIconType`, a combination the type forbids.
    const alias = new RegExp(`type\\\\s+${preferredTypeName}\\\\s*=\\\\s*([^;{]+);`).exec(content)
    if (alias && alias[1].includes('|')) {
      const memberNames = alias[1].split('|').map((s) => s.trim())

      // A member is usually an intersection — `ZimmButtonBaseProps & {…}` — so its own literal
      // holds only the variant-specific half. Reading that alone silently drops the shared props
      // (ZimmButton's `label` lives entirely in the base), so follow the intersection. Scoped to
      // this branch deliberately: the object-literal fast path above already produces accepted
      // rows, and resolving ancestors there too would churn unrelated entries for no fix.
      const resolveProps = ({typeName, prefix, props}, seen = new Set([typeName])) => {
        const inherited = []
        for (const [, ancestorName] of prefix.matchAll(/(\\w*Props)/g)) {
          if (seen.has(ancestorName)) continue
          seen.add(ancestorName)
          const ancestor = allBlocks.find((b) => b.typeName === ancestorName)
          if (ancestor) inherited.push(...resolveProps(ancestor, seen))
        }
        return [...inherited, ...props]
      }

      const members = memberNames
        .map((name) => allBlocks.find(({typeName}) => typeName === name))
        .filter(Boolean)
        .map((block) => ({props: resolveProps(block)}))

      // Members declared in another file can't be resolved from this content. Surface the union
      // expression rather than falling through to the merge that misreports it.
      if (!members.length) return [memberNames.join(' | ')]

      // A prop carried by every member is unconditionally present; one carried by only some is
      // conditional on which variant you picked, which is exactly what `?` means at the union.
      const nameOf = (prop) => prop.split(/[?:]/)[0]
      const memberCount = new Map()
      for (const {props: memberProps} of members) {
        for (const name of new Set(memberProps.map(nameOf))) {
          memberCount.set(name, (memberCount.get(name) ?? 0) + 1)
        }
      }

      const unionProps = []
      const unionSeen = new Set()
      for (const {props: memberProps} of members) {
        for (const prop of memberProps) {
          const name = nameOf(prop)
          if (unionSeen.has(name)) continue
          unionSeen.add(name)
          unionProps.push(
            memberCount.get(name) === members.length ? prop : prop.replace(/^(\\w+)\\??:/, '$1?:'),
          )
        }
      }
      return unionProps
    }
  }
"""
