from pathlib import Path
p = Path('scripts/generateRegistry.mjs')
s = p.read_text()

start = s.index('      const members = memberNames')
end = s.index('      return unionProps', start) + len('      return unionProps')

new = '''      // All-or-nothing: a member declared in another file can't be resolved from this content, and
      // publishing the members that did resolve would present a partial union as a complete one —
      // worse, with `members.length` shrunk to match, every surviving prop would satisfy the
      // present-in-every-member test below and be reported required. Surface the union expression.
      const resolved = memberNames.map((name) => allBlocks.find(({typeName}) => typeName === name))
      if (resolved.some((block) => !block)) return [memberNames.join(' | ')]

      const nameOf = (prop) => prop.split(/[?:]/)[0]
      const typeOf = (prop) => prop.slice(prop.indexOf(':') + 1).trim()

      // Per member, collapse its own resolved props into one fact per name. An intersection can
      // declare the same prop twice (the base's `label: string` plus the member's own literal);
      // `A & B` must satisfy both, so the member requires the prop if any declaration does.
      const memberFacts = resolved.map((block) => {
        const facts = new Map()
        for (const prop of resolveProps(block)) {
          const name = nameOf(prop)
          const required = !/^\\w+\\?:/.test(prop)
          const prev = facts.get(name)
          if (prev) {
            prev.required = prev.required || required
            if (!prev.types.includes(typeOf(prop))) prev.types.push(typeOf(prop))
          } else {
            facts.set(name, {required, types: [typeOf(prop)]})
          }
        }
        return facts
      })

      // At the union a prop is required only where every member carries it *and* every member
      // declares it without `?` — presence alone isn't enough, or a prop that one variant makes
      // optional gets published as mandatory. Types are unioned across members rather than taken
      // from whichever member happened to be declared first, so the row no longer depends on the
      // order of the alias' operands.
      const unionProps = []
      for (const name of new Set(memberFacts.flatMap((facts) => [...facts.keys()]))) {
        const carriedByAll = memberFacts.every((facts) => facts.has(name))
        const requiredByAll = carriedByAll && memberFacts.every((facts) => facts.get(name).required)
        const types = []
        for (const facts of memberFacts) {
          for (const type of facts.get(name)?.types ?? []) {
            if (!types.includes(type)) types.push(type)
          }
        }
        unionProps.push(`${name}${requiredByAll ? '' : '?'}: ${types.join(' | ')}`)
      }
      return unionProps'''

p.write_text(s[:start] + new + s[end:])
print('  replaced union resolution block')
