cd /Users/marcel.a.n.navarro/Dev/zimmermann-pwa
python3 - <<'PY'
from pathlib import Path

# ── FIX 1: modal story — the portal mounts on the 2nd pass, so await it ──
p = Path('overrides/app/components/ui-kits/organisms/zimmSubscribeModal/index.stories.tsx')
s = p.read_text()
old = """  play: async () => {
    const doc = within(document.body);
    await expect(doc.getByRole('dialog')).toBeInTheDocument();
    await expect(doc.getByRole('heading', { name: /join us/i })).toBeInTheDocument();
    await expect(doc.getByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
  },"""
new = """  // ZimmModal gates its portal on `mounted`, which useZimmModal flips in a useEffect, so the
  // dialog does not exist on the first render pass. These must be async finders — a synchronous
  // getByRole runs before that re-render and fails with "unable to find role dialog".
  play: async () => {
    const doc = within(document.body);
    await expect(await doc.findByRole('dialog')).toBeInTheDocument();
    await expect(await doc.findByRole('heading', { name: /join us/i })).toBeInTheDocument();
    await expect(await doc.findByRole('link', { name: /privacy policy/i })).toBeInTheDocument();
  },"""
assert s.count(old) == 1, f'modal play anchor: {s.count(old)}'
p.write_text(s.replace(old, new))
print('  ✅ 1/3 modal story — synchronous getByRole → async findByRole')

# ── FIX 2: subscribe section — give axe a real background to measure against ──
p = Path('overrides/app/components/ui-kits/organisms/zimmSubscribeSection/index.stories.tsx')
s = p.read_text()
old = """  parameters: { backgrounds: { default: 'dark' } },"""
new = """  parameters: { backgrounds: { default: 'dark' } },
  // The backgrounds addon colours the preview iframe, not a DOM ancestor of the component, so
  // axe resolves the effective background as white and reports the caption text (text.inverseGrey,
  // #969696) as 2.95:1. In the shipped footer this sits on background.05 — footer.css.ts:25's
  // var(--zimm-color-bg-05), #191919 — which is 5.94:1 and passes AA. This decorator reproduces
  // that real context so the a11y check measures what actually ships.
  decorators: [
    (Story) => (
      <div style={{ backgroundColor: 'var(--zimm-color-bg-05)', padding: 'var(--zimm-scale-xl)' }}>
        <Story />
      </div>
    ),
  ],"""
assert s.count(old) == 1, f'section params anchor: {s.count(old)}'
p.write_text(s.replace(old, new))
print('  ✅ 2/3 subscribe section — decorator supplies the real background.05')
PY

