/**
 * Generic chrome only — no mount/focus/keyboard mechanics here, since those live in
 * useZimmModal and are paired at the call site (see Forms/ZimmSubscribeModal for a real
 * consumer with the full dialog behaviour). This story proves the portal/overlay/panel render
 * with the expected dialog semantics.
 */
export const Default: Story = {
  render: () => {
    const [isOpen, setIsOpen] = useState(true);
    return (
      <ZimmModal
        isOpen={isOpen}
        mounted
        onClose={() => setIsOpen(false)}
        maxWidth="24rem"
        labelledBy="zimm-modal-story-title"
      >
        <chakra.h2 id="zimm-modal-story-title">Example dialog</chakra.h2>
        <chakra.p>Generic ZimmModal chrome with arbitrary children.</chakra.p>
      </ZimmModal>
    );
  },
  play: async () => {
    const doc = within(document.body);
    const dialog = doc.getByRole('dialog');
    await expect(dialog).toBeInTheDocument();
    await expect(dialog).toHaveAttribute('aria-modal', 'true');
    await expect(doc.getByRole('heading', { name: /example dialog/i })).toBeInTheDocument();
  },
};

