import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { filterByRegion, pickMostSpecificByRegion } from './resolveByRegion';

type Fixture = {
  sys: { id: string; updatedAt?: string };
  fields: { regions?: ReadonlyArray<{ fields: { siteId: string } }> };
};

const region = (siteId: string) => ({ fields: { siteId } });

const entry = (id: string, siteIds?: string[], updatedAt?: string): Fixture => ({
  sys: { id, updatedAt },
  fields: { regions: siteIds ? siteIds.map(region) : undefined },
});

describe('filterByRegion', () => {
  test('keeps a global (unscoped) entry for any site', () => {
    const global = entry('global');
    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
  });

  test('keeps a global entry with an explicitly empty regions array', () => {
    const global = entry('global', []);
    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
  });

  test('keeps an entry whose regions include the current site', () => {
    const us = entry('us', ['ZimmermannUS']);
    expect(filterByRegion([us], 'ZimmermannUS')).toEqual([us]);
  });

  test('drops an entry scoped to other sites only', () => {
    const au = entry('au', ['ZimmermannAU']);
    expect(filterByRegion([au], 'ZimmermannUS')).toEqual([]);
  });

  test('keeps multiple non-conflicting eligible entries', () => {
    const global = entry('global');
    const us = entry('us', ['ZimmermannUS']);
    const au = entry('au', ['ZimmermannAU']);
    expect(filterByRegion([global, us, au], 'ZimmermannUS')).toEqual([global, us]);
  });
});

describe('pickMostSpecificByRegion', () => {
  test('returns undefined when no candidates are eligible', () => {
    const au = entry('au', ['ZimmermannAU']);
    expect(pickMostSpecificByRegion([au], 'ZimmermannUS')).toBeUndefined();
  });

  test('returns the global fallback when no regional entry exists', () => {
    const global = entry('global');
    expect(pickMostSpecificByRegion([global], 'ZimmermannUS')).toBe(global);
  });

  test('a US-scoped override wins over a broader global entry', () => {
    const global = entry('global');
    const usOverride = entry('us-override', ['ZimmermannUS']);
    expect(pickMostSpecificByRegion([global, usOverride], 'ZimmermannUS')).toBe(usOverride);
  });

  test('narrower regions array wins over a broader (but still eligible) one', () => {
    const broad = entry('broad', ['ZimmermannUS', 'ZimmermannAU']);
    const narrow = entry('narrow', ['ZimmermannUS']);
    expect(pickMostSpecificByRegion([broad, narrow], 'ZimmermannUS')).toBe(narrow);
  });

  describe('tie-break', () => {
    beforeEach(() => {
      vi.spyOn(console, 'warn').mockImplementation(() => {});
    });

    afterEach(() => {
      vi.restoreAllMocks();
    });

    test('two equally-scoped entries resolve to the most recently updated, and warn', () => {
      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([older, newer], 'ZimmermannUS')).toBe(newer);
      expect(console.warn).toHaveBeenCalledTimes(1);
    });

    test('order of the tied candidates in the input does not change the outcome', () => {
      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([newer, older], 'ZimmermannUS')).toBe(newer);
    });
  });
});

