// A finding is resolved only if it is a conflict this run explicitly adopts. The gate used to
// ask `!(conflictingIds.length && TAKEOVER_IDS.length)`, which is a proxy, not a check: any
// non-empty --takeover combined with any conflict existing disabled the gate for *every*
// finding. Three ways that let an unresolved finding through — one adopted conflict alongside a
// finding of some other class; three conflicts with only one adopted; or a --takeover naming an
// id that resolves nothing. `message` is typed as an open string by the SDK, so nothing
// constrains findings to the one class this script knows how to adopt.
const takeoverSet = new Set(TAKEOVER_IDS);
const unresolved = (validation.items ?? []).filter(
  (f) => !(f.message === 'conflictingContentTypes' && takeoverSet.has(f.details?.contentTypeId)),
);

const unknownTakeovers = TAKEOVER_IDS.filter((id) => !conflictingIds.includes(id));
if (unknownTakeovers.length) {
  log.warn(`--takeover ids not present in the conflict list (typo?): ${unknownTakeovers.join(', ')}`);
}

if (unresolved.length && !FORCE) {
  log.error(
    `Refusing to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s). Pass --force to override.`,
  );
  for (const finding of unresolved) {
    console.log(`    unresolved: ${finding.message}${finding.details?.contentTypeId ? ` (${finding.details.contentTypeId})` : ''}`);
  }
  process.exit(1);
}

