// A finding counts as resolved only if it is a conflictingContentTypes finding whose specific
// content type was named in --takeover. The previous form, `!(conflictingIds.length &&
// TAKEOVER_IDS.length)`, tested only that *some* conflict existed and *some* takeover was
// passed — so `--takeover a` alongside one conflict opened the gate for every other finding
// too, including findings of a class this script doesn't handle (the SDK types `message` as an
// open string, not a union). Three findings could reach a live install unreviewed that way:
// an unrelated finding riding alongside one conflict, conflicts b and c when only a was
// adopted, and a --takeover naming an id that resolves nothing.
const takeoverSet = new Set(TAKEOVER_IDS);
const unresolved = (validation.items ?? []).filter(
  (finding) => !(finding.message === 'conflictingContentTypes' && takeoverSet.has(finding.details?.contentTypeId)),
);

const unknownTakeovers = TAKEOVER_IDS.filter((id) => !conflictingIds.includes(id));
if (unknownTakeovers.length) {
  log.warn(`--takeover named ${unknownTakeovers.join(', ')}, which are not in the conflict list. Typo?`);
}

if (unresolved.length && !FORCE) {
  log.error(
    `Refusing to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s). ` +
      `Pass --force to override.`,
  );
  for (const finding of unresolved) {
    console.error(`    unresolved: ${finding.message}${finding.details?.contentTypeId ? ` (${finding.details.contentTypeId})` : ''}`);
  }
  process.exit(1);
}

