#!/usr/bin/env node
/**
 * Install (or update) the Zimmermann Environment Template into one target environment.
 *
 * Replaces the old runMigrations.mjs promotion flow. There is no more hand-rolled
 * '_migrationHistory' content type or detectDrift.mjs — Contentful tracks each
 * environment's install status/version natively via environmentTemplateInstallation,
 * and cross-environment content-type drift can't happen the way it used to since every
 * environment installs from the same versioned template.
 *
 * Usage:
 *   npm run sync:contentful                            # author the template first (buildTemplate.js)
 *   npm run install:contentful -- --target dev
 *   npm run install:contentful -- --target sit --dry-run
 *
 * If validation reports a content type that already exists in the target environment
 * but isn't managed by this template (e.g. one created by the old sync.js pipeline
 * before this template-based approach existed), the install is refused by Contentful.
 * Adopt it into the template explicitly rather than deleting it first:
 *   npm run install:contentful -- --target dev --takeover shoppableImage,otherType
 *
 * Promotion order: dev → test → sit → staging → uat → master (via production alias)
 */

import { checkEnv, createClient, log } from './_shared.mjs';

const args = process.argv.slice(2);
const getArg = (flag) => {
  const i = args.indexOf(flag);
  return i !== -1 ? args[i + 1] : null;
};

const TARGET = getArg('--target');
const DRY_RUN = args.includes('--dry-run');
const FORCE = args.includes('--force');
const DELETE_DELETED_FIELDS = args.includes('--delete-deleted-fields');
const TAKEOVER_IDS = (getArg('--takeover') ?? '')
  .split(',')
  .map((s) => s.trim())
  .filter(Boolean);

if (!TARGET) {
  log.error('--target <environmentId> is required.');
  console.error('  Example: npm run install:contentful -- --target dev\n');
  console.error('  Promotion order: dev → test → sit → staging → uat → master\n');
  process.exit(1);
}

// Must match TEMPLATE_NAME in ../buildTemplate.js — the template is looked up by name,
// not a stored ID, so the two files just need to agree on the literal.
const TEMPLATE_NAME = 'Zimmermann Content Model';

const TERMINAL_STATUSES = new Set(['succeeded', 'failed', 'disconnected']);

async function pollInstallation(
  client,
  { organizationId, spaceId, environmentId, environmentTemplateId },
  timeoutMs = 120_000,
) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const { items } = await client.environmentTemplateInstallation.getForEnvironment({
      spaceId,
      environmentId,
      environmentTemplateId,
      limit: 1,
    });
    const [latest] = items;
    if (latest && TERMINAL_STATUSES.has(latest.sys.status)) return latest;
    await new Promise((r) => setTimeout(r, 3_000));
    process.stdout.write('.');
  }
  throw new Error(`Installation into '${environmentId}' did not reach a terminal status within ${timeoutMs / 1000}s`);
}

async function main() {
  checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_ORGANIZATION_ID', 'CONTENTFUL_SPACE_ID']);

  const organizationId = process.env.CONTENTFUL_ORGANIZATION_ID;
  const spaceId = process.env.CONTENTFUL_SPACE_ID;

  const client = createClient();

  const { items: templates } = await client.environmentTemplate.getMany({ organizationId, query: { limit: 100 } });
  const template = templates.find((t) => t.name === TEMPLATE_NAME);

  if (!template) {
    log.error(`No EnvironmentTemplate named "${TEMPLATE_NAME}" found in organization '${organizationId}'.`);
    console.error('  Run `npm run build:contentful` first.\n');
    process.exit(1);
  }

  log.section(`Install → '${TARGET}'`);
  console.log(`  Template: "${TEMPLATE_NAME}" (version ${template.sys.version})`);

  log.info('Validating...');
  const validation = await client.environmentTemplate.validate(
    { spaceId, environmentId: TARGET, environmentTemplateId: template.sys.id, version: template.sys.version },
    {},
  );

  const conflictingIds = (validation.items ?? [])
    .filter((f) => f.message === 'conflictingContentTypes')
    .map((f) => f.details?.contentTypeId)
    .filter(Boolean);

  if (validation.items?.length) {
    log.warn('Validation findings:');
    for (const finding of validation.items) {
      console.log(`    ${finding.message}${finding.details?.message ? ` — ${finding.details.message}` : ''}`);
    }
    if (conflictingIds.length && !TAKEOVER_IDS.length) {
      console.log(
        `\n  These content types already exist in '${TARGET}' but aren't managed by this template.\n` +
          `  Re-run with --takeover ${conflictingIds.join(',')} to adopt them, once you've confirmed that's intended.\n`,
      );
    }
  } else {
    log.success('No validation findings.');
  }


  // A finding is resolved only if it is a conflict this run explicitly adopts. The gate used to
  // test `!(conflictingIds.length && TAKEOVER_IDS.length)`, which asked "is there at least one
  // conflict and at least one takeover?" rather than "is every finding accounted for" — so any
  // single --takeover opened the gate for every *other* finding too, including conflicts it
  // didn't name and findings of unrelated classes. `message` is an open string in the SDK's
  // types, so the set of classes isn't bounded by the one handled here.
  const takeoverSet = new Set(TAKEOVER_IDS);
  const unresolved = (validation.items ?? []).filter(
    (f) => !(f.message === 'conflictingContentTypes' && takeoverSet.has(f.details?.contentTypeId)),
  );

  const unknownTakeovers = TAKEOVER_IDS.filter((id) => !conflictingIds.includes(id));
  if (unknownTakeovers.length) {
    log.warn(
      `--takeover names ${unknownTakeovers.join(', ')}, which ${unknownTakeovers.length === 1 ? 'is' : 'are'} not in the conflict list — typo? Adopting nothing for ${unknownTakeovers.length === 1 ? 'it' : 'them'}.`,
    );
  }

  if (DRY_RUN) {
    // Reported after the unresolved set is computed, not before it. Previously dry-run returned
    // ahead of the gate and always printed "Would install", which made it useless as a pre-flight
    // for the one check it most needed to preview. Still exits 0 — a dry run reports, it doesn't
    // adjudicate.
    if (unresolved.length && !FORCE) {
      log.warn(
        `[dry-run] Would REFUSE to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s).`,
      );
    } else {
      log.info(`[dry-run] Would install template version ${template.sys.version} into '${TARGET}'.`);
    }
    return;
  }

  if (unresolved.length && !FORCE) {
    log.error(
      `Refusing to install into '${TARGET}' — ${unresolved.length} unresolved validation finding(s). Pass --force to override.`,
    );
    for (const finding of unresolved) {
      console.log(`    ${finding.message}${finding.details?.contentTypeId ? ` (${finding.details.contentTypeId})` : ''}`);
    }
    process.exit(1);
  }

  // Send only ids Contentful actually reported as conflicting. The warning above tells the
  // operator that unknown ids adopt nothing; this is what makes that true rather than merely
  // stated — otherwise a typo'd id is still POSTed as a ContentType link to adopt.
  const adoptableIds = TAKEOVER_IDS.filter((id) => conflictingIds.includes(id));
  const takeover = adoptableIds.length
    ? { items: adoptableIds.map((id) => ({ sys: { type: 'Link', linkType: 'ContentType', id } })) }
    : undefined;

  log.info(`Installing into '${TARGET}'...`);
  await client.environmentTemplate.install(
    { spaceId, environmentId: TARGET, environmentTemplateId: template.sys.id },
    { version: template.sys.version, deleteDeletedFields: DELETE_DELETED_FIELDS, takeover },
  );

  const result = await pollInstallation(client, {
    organizationId,
    spaceId,
    environmentId: TARGET,
    environmentTemplateId: template.sys.id,
  });

  if (result.sys.status === 'succeeded') {
    console.log(`\n  ✅  Installed template version ${template.sys.version} into '${TARGET}'.\n`);
  } else {
    log.error(`Installation into '${TARGET}' ended with status '${result.sys.status}'.`);
    if (result.sys.errors) console.error(JSON.stringify(result.sys.errors, null, 2));
    process.exit(1);
  }
}

main().catch((err) => {
  log.error(err.message ?? err);
  process.exit(1);
});

/**
 * Generic region-scoping resolution for Contentful entries carrying a `regions`
 * reference field (see overrides/app/types/contentful.ts's RegionEntry / LinkEntry /
 * FooterConfigEntry). Not footer-specific — works against any entry shaped this way.
 *
 * An entry with an omitted or empty `regions` array is the global/default case: it
 * matches every site and is the *least* specific match. An entry scoping `regions` to
 * fewer sites is more specific than one scoping it to more.
 */

type RegionRef = { fields: { siteId: string } };

type RegionAwareEntry = {
  // Index signature deliberately widens this past a TS "weak type" (all-optional, no
  // index signature) — without it, a concrete Contentful entry's `sys: {id, contentType}`
  // shares zero properties with `{updatedAt?}` and fails the generic constraint check below,
  // even though it's exactly the shape this utility exists to accept.
  sys?: { updatedAt?: string; [key: string]: unknown };
  fields: { regions?: ReadonlyArray<RegionRef> };
};

const isEligible = (entry: RegionAwareEntry, siteId: string): boolean => {
  const regions = entry.fields.regions;
  if (!regions || regions.length === 0) return true;
  return regions.some((region) => region.fields.siteId === siteId);
};

/** Fewer regions = more specific. Global/unscoped (empty or omitted) sorts last. */
const specificity = (entry: RegionAwareEntry): number =>
  entry.fields.regions && entry.fields.regions.length > 0 ? entry.fields.regions.length : Infinity;

/**
 * Inclusive filter — every entry eligible for `siteId` is kept, no precedence applied.
 * Use for arrays where multiple non-conflicting regional entries can legitimately
 * coexist in the same rendered list (e.g. links inside a shared footerNavGroup).
 */
export function filterByRegion<T extends RegionAwareEntry>(entries: readonly T[], siteId: string): T[] {
  return entries.filter((entry) => isEligible(entry, siteId));
}

/**
 * Single-winner resolution — picks the most specific entry eligible for `siteId`. Use
 * for a root entry where only one should render (e.g. which footerConfig to use for
 * the current site).
 *
 * A tie between two equally-scoped entries is an editorial mistake the additive-only sync
 * pipeline doesn't prevent (nothing stops two entries both scoping to e.g. exactly
 * ['ZimmermannUS'] — or two unscoped entries, which tie at Infinity). Resolved
 * deterministically by most-recently-updated, then by `sys.id` when those match, rather than
 * by CDA response order — and a console.warn fires on every tie, whichever side wins, so the
 * duplicate entry can be cleaned up. Fires n-1 times for an n-way tie, once per mount.
 */
export function pickMostSpecificByRegion<T extends RegionAwareEntry>(
  candidates: readonly T[],
  siteId: string,
): T | undefined {
  const eligible = filterByRegion(candidates, siteId);

  let best: T | undefined;
  let bestSpecificity = Infinity;

  for (const candidate of eligible) {
    const candidateSpecificity = specificity(candidate);

    if (best === undefined || candidateSpecificity < bestSpecificity) {
      best = candidate;
      bestSpecificity = candidateSpecificity;
      continue;
    }

    if (candidateSpecificity === bestSpecificity) {
      // The warn sits outside the comparison on purpose. It used to live inside the
      // most-recently-updated check, which meant it only fired when the candidate happened to be
      // newer than the incumbent — so a tie already arriving newest-first, or one where both
      // entries share an updatedAt, was resolved silently. The tie itself is the editorial
      // mistake worth surfacing, regardless of which side of it wins.
      console.warn(
        `resolveByRegion: tie between two equally-scoped entries for region "${siteId}" — resolving by most-recently-updated, then by sys.id.`,
      );

      const bestUpdatedAt = best.sys?.updatedAt ?? '';
      const candidateUpdatedAt = candidate.sys?.updatedAt ?? '';
      // `sys.id` breaks a dead heat. Without it, equal (or absent) timestamps left the winner
      // decided by whichever entry the CDA happened to return first — and `getEntries` is called
      // with no `order`, so that isn't stable across requests.
      const bestId = String(best.sys?.id ?? '');
      const candidateId = String(candidate.sys?.id ?? '');
      if (candidateUpdatedAt > bestUpdatedAt || (candidateUpdatedAt === bestUpdatedAt && candidateId < bestId)) {
        best = candidate;
      }
    }
  }

  return best;
}

import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { filterByRegion, pickMostSpecificByRegion } from './resolveByRegion';

type Fixture = {
  sys: { id: string; updatedAt?: string };
  fields: { regions?: ReadonlyArray<{ fields: { siteId: string } }> };
};

const region = (siteId: string) => ({ fields: { siteId } });

const entry = (id: string, siteIds?: string[], updatedAt?: string): Fixture => ({
  sys: { id, updatedAt },
  fields: { regions: siteIds ? siteIds.map(region) : undefined },
});

describe('filterByRegion', () => {
  test('keeps a global (unscoped) entry for any site', () => {
    const global = entry('global');
    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
  });

  test('keeps a global entry with an explicitly empty regions array', () => {
    const global = entry('global', []);
    expect(filterByRegion([global], 'ZimmermannUS')).toEqual([global]);
  });

  test('keeps an entry whose regions include the current site', () => {
    const us = entry('us', ['ZimmermannUS']);
    expect(filterByRegion([us], 'ZimmermannUS')).toEqual([us]);
  });

  test('drops an entry scoped to other sites only', () => {
    const au = entry('au', ['ZimmermannAU']);
    expect(filterByRegion([au], 'ZimmermannUS')).toEqual([]);
  });

  test('keeps multiple non-conflicting eligible entries', () => {
    const global = entry('global');
    const us = entry('us', ['ZimmermannUS']);
    const au = entry('au', ['ZimmermannAU']);
    expect(filterByRegion([global, us, au], 'ZimmermannUS')).toEqual([global, us]);
  });
});

describe('pickMostSpecificByRegion', () => {
  test('returns undefined when no candidates are eligible', () => {
    const au = entry('au', ['ZimmermannAU']);
    expect(pickMostSpecificByRegion([au], 'ZimmermannUS')).toBeUndefined();
  });

  test('returns the global fallback when no regional entry exists', () => {
    const global = entry('global');
    expect(pickMostSpecificByRegion([global], 'ZimmermannUS')).toBe(global);
  });

  test('a US-scoped override wins over a broader global entry', () => {
    const global = entry('global');
    const usOverride = entry('us-override', ['ZimmermannUS']);
    expect(pickMostSpecificByRegion([global, usOverride], 'ZimmermannUS')).toBe(usOverride);
  });

  test('narrower regions array wins over a broader (but still eligible) one', () => {
    const broad = entry('broad', ['ZimmermannUS', 'ZimmermannAU']);
    const narrow = entry('narrow', ['ZimmermannUS']);
    expect(pickMostSpecificByRegion([broad, narrow], 'ZimmermannUS')).toBe(narrow);
  });

  describe('tie-break', () => {
    beforeEach(() => {
      vi.spyOn(console, 'warn').mockImplementation(() => {});
    });

    afterEach(() => {
      vi.restoreAllMocks();
    });

    test('two equally-scoped entries resolve to the most recently updated, and warn', () => {
      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([older, newer], 'ZimmermannUS')).toBe(newer);
      expect(console.warn).toHaveBeenCalledTimes(1);
    });

    test('distinct timestamps resolve the same way whichever order they arrive in', () => {
      const older = entry('older', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
      const newer = entry('newer', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([newer, older], 'ZimmermannUS')).toBe(newer);
      // Previously the warn lived inside the `candidateUpdatedAt > bestUpdatedAt` branch, so a tie
      // already arriving newest-first resolved silently. Asserting it here is what pins that.
      expect(console.warn).toHaveBeenCalledTimes(1);
    });

    // The three cases below were invisible to this suite before: the test above only used
    // *distinct* timestamps, which is the one arrangement that was already order-independent.
    test('identical timestamps resolve by sys.id, not by input order', () => {
      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
    });

    test('absent timestamps resolve by sys.id, not by input order', () => {
      const alpha = entry('alpha', ['ZimmermannUS']);
      const beta = entry('beta', ['ZimmermannUS']);
      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
    });

    // [alpha, beta], not [beta, alpha]: in the latter the candidate wins on sys.id, so the warn
    // fires even if it were still nested inside the comparison. Only the losing-candidate order
    // distinguishes "warns on every tie" from "warns when the candidate happens to win".
    test('warns on a tie even when the incumbent keeps the win', () => {
      const alpha = entry('alpha', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      const beta = entry('beta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([alpha, beta], 'ZimmermannUS')).toBe(alpha);
      expect(console.warn).toHaveBeenCalledTimes(1);
    });

    // sys.id is the *secondary* key. Fixtures deliberately sort id-ascending against
    // timestamp-descending, so dropping the `updatedAt === updatedAt` guard — which would promote
    // sys.id to primary — flips the winner and fails here.
    test('a newer timestamp beats a lower sys.id', () => {
      const zeta = entry('zeta', ['ZimmermannUS'], '2026-06-01T00:00:00.000Z');
      const alpha = entry('alpha', ['ZimmermannUS'], '2026-01-01T00:00:00.000Z');
      expect(pickMostSpecificByRegion([zeta, alpha], 'ZimmermannUS')).toBe(zeta);
      expect(pickMostSpecificByRegion([alpha, zeta], 'ZimmermannUS')).toBe(zeta);
    });

    test('two unscoped entries also tie, and warn', () => {
      const alpha = entry('alpha');
      const beta = entry('beta');
      expect(pickMostSpecificByRegion([beta, alpha], 'ZimmermannUS')).toBe(alpha);
      expect(console.warn).toHaveBeenCalledTimes(1);
    });
  });
});

