══════════ footerNavColumn.css.ts ══════════
import { BP, SIZE_COL_NAV } from 'app/theme/components/footerShared';

export const ZimmFooterNavColumn = {
  parts: ['col', 'heading', 'list', 'listItem'],
  baseStyle: {
    // Figma: flex-col, gap-16px, 140px wide on mobile; content-sized on tablet+ but CAPPED.
    //
    // The cap reproduces a per-item constraint in the design. Figma's "ACKNOWLEDGEMENT OF
    // COUNTRY" item (40000407:11004) is 118x38 — its 118px is the box AFTER wrapping (the
    // width of the word "ACKNOWLEDGEMENT"), not its natural width, which is ~188px. Every other
    // nav label is narrower and stays on one line, including "BOOK AN APPOINTMENT" at 135x24.
    // So the design's implicit threshold sits between 135 and 188.
    //
    // 160px (--zimm-scale-7xl) is inside that window under BOTH fonts, which matters because
    // the fallback stack renders ~13% wider than Futura Round. Both are measured because the
    // cap has to hold before the self-hosted face loads as well as after. Widths, fallback /
    // Futura:
    //   ACKNOWLEDGEMENT OF COUNTRY  212 / ~188  -> wraps under both            (> 160)
    //   "ACKNOWLEDGEMENT" alone     130 / ~115  -> break lands after it        (< 160)
    //   BOOK AN APPOINTMENT         149 / ~135  -> stays on one line under both (< 160)
    // A 140px cap (SIZE_COL_NAV) was tried first and wrongly wrapped BOOK AN APPOINTMENT.
    //
    // Exact column widths still will not match Figma (Help 120 vs 106) — those are
    // content-driven and follow the font. Not a build defect.
    // Pending Kiera: confirm a column cap is the right rule vs a per-item wrap.
    col: {
      display: 'flex',
      flexDirection: 'column',
      gap: 'var(--zimm-scale-m)',
      alignItems: 'flex-start',
      width: SIZE_COL_NAV,
      minWidth: 0,
      flexShrink: 0,
      [`@media (min-width: ${BP.tablet})`]: {
        width: 'auto',
        maxWidth: 'var(--zimm-scale-7xl)', // 10rem (160px) — see the threshold note above
        flexShrink: 1,
      },
    },

    // Nav column headings (About / Contact / Help) — Figma "Default/Navigation".
    // fontFamily overrides the heading family textStyles.navigation carries: Figma binds
    // brand/font/family/body here (node 40000407:11736).
    heading: {
      textStyle: 'navigation',
      fontFamily: 'var(--zimm-font-family-body)',
      margin: 0,
      color: 'var(--zimm-color-text-inverse-grey)', // alias/color/text/inverse/subtle
    },

    // Figma Links div: flex-col, items-start, width 100%.
    list: {
      listStyle: 'none',
      padding: 0,
      margin: 0,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      width: '100%',
      gap: 0,
    },

    // display:flex, not the default list-item. ZimmNavItem renders an inline-flex <a> of
    // exactly 24px, but a block-level <li> wraps it in a line box whose 24px strut adds
    // descender space below the baseline — measured 25.5px against the anchor's 24px. That
    // 1.5px leaked once per row (and 3px on the wrapped "Acknowledgement of Country"), making
    // the links column 9px taller than Figma's 158px. Making the <li> a flex container removes
    // the line box entirely, so its height is just the anchor's.
    listItem: { listStyle: 'none', display: 'flex' },
  },
};

══════════ bottomBar.css.ts ══════════
import { BP, SIZE_COL_NAV } from 'app/theme/components/footerShared';

export const ZimmFooterBottomBar = {
  parts: ['bar', 'inner', 'right', 'copyright', 'legalLink', 'legalGrid', 'localeText', 'localeButton'],
  baseStyle: {
    bar: {
      backgroundColor: 'var(--zimm-color-bg-06)',
      width: '100%',
    },

    // Figma: stacked column on mobile, single row on tablet+
    inner: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: 0,
      padding: 'var(--zimm-scale-xl) var(--zimm-scale-2xl)',
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
        // Gutter widens here, not at BP.desktop. footer.css.ts's contentRow and logo both step
        // from 2xl to 3xl at BP.tablet, so holding this at 2xl until 1024px left the whole
        // 768-1023px band with the bottom bar inset 8px less than the content above it — the
        // locale control and the legal links sat left of the subscribe column and the logo.
        padding: 'var(--zimm-scale-xl) var(--zimm-scale-3xl)',
      },
    },

    // Right group: copyright span + legalGrid div stacked on mobile, flex-row on tablet.
    // copyright is a direct flex child (no wrapper div) to match Figma's flat Legal row.
    right: {
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      gap: 'var(--zimm-scale-xs)',
      width: '100%',
      [`@media (min-width: ${BP.tablet})`]: {
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'flex-end',
        gap: `0 var(--zimm-scale-xl)`,
        width: 'auto',
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: `0 var(--zimm-scale-2xl)`,
      },
    },

    // Copyright + legal links share the footer text style; py-8px matches Figma Small/Default.
    copyright: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-muted)',
      whiteSpace: 'nowrap',
      paddingY: 'var(--zimm-scale-xs)',
      paddingX: 0,
    },
    legalLink: {
      textStyle: 'footer',
      color: 'var(--zimm-color-text-muted)',
      justifyContent: 'flex-start',
      // No height override — ZimmNavItem's baseStyle uses minHeight, so the py-8px below grows
      // the item naturally. Figma Small/Default: py-[8px].
      paddingY: 'var(--zimm-scale-xs)',
      paddingX: 0,
    },

    // Legal links: 2-col flex-wrap grid on mobile; inline flex row inside `right` at tablet+.
    // Avoids display:contents (unreliable in Emotion __css media queries) — legalGrid stays a
    // normal flex container but switches from a full-width wrap to an auto-width nowrap row.
    legalGrid: {
      display: 'flex',
      flexWrap: 'wrap',
      alignContent: 'flex-start',
      gap: `0 var(--zimm-scale-3xl)`,
      width: '100%',
      '& > a': { width: SIZE_COL_NAV },
      [`@media (min-width: ${BP.tablet})`]: {
        flexWrap: 'nowrap',
        gap: `0 var(--zimm-scale-xl)`,
        width: 'auto',
        '& > a': { width: 'auto' },
      },
      [`@media (min-width: ${BP.desktop})`]: {
        gap: `0 var(--zimm-scale-2xl)`,
      },
    },

    // Locale button inner text span — py-8px at EVERY breakpoint. Figma's Language item is h=23
    // (8px + 7px text + 8px) identically on desktop (40000407:14372) and mobile
    // (40000407:23934), and its Legal row opposite is also h=23, so both ends of the bottom bar
    // share a height. A previous tablet+ `padding: 0` override collapsed this to 14px against
    // the 31px legal links — removed.
    localeText: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      paddingY: 'var(--zimm-scale-xs)',
      paddingX: 0,
      whiteSpace: 'nowrap',
    },

