import { chromium } from 'playwright';

const PORT = process.env.PORT || 6099;
const URL = `http://127.0.0.1:${PORT}/iframe.html?id=layout-footer--default&viewMode=story`;
const WIDTHS = [402, 768, 800, 830, 859, 860, 880, 900, 950, 1000, 1023, 1024, 1100, 1280, 1440];

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto(URL, { waitUntil: 'domcontentloaded' });
await page.waitForSelector('footer[role=contentinfo]', { timeout: 15000 });
await page.evaluate(() => document.fonts.ready);
await page.waitForTimeout(300);

// Prove which font is actually rendering: measure the same string in the real stack vs a
// deliberately-bogus family. Equal widths => the real face never loaded.
const fontProbe = await page.evaluate(() => {
  const mk = (fam) => {
    const s = document.createElement('span');
    s.textContent = 'BOOK AN APPOINTMENT';
    s.style.cssText = `position:absolute;visibility:hidden;white-space:nowrap;font-size:14px;font-family:${fam}`;
    document.body.appendChild(s); const w = s.getBoundingClientRect().width; s.remove(); return w;
  };
  return { real: mk("'Futura Round', sans-serif"), bogus: mk("'__NoSuchFace__', sans-serif") };
});

const rows = [];
for (const width of WIDTHS) {
  await page.setViewportSize({ width, height: 900 });
  await page.waitForTimeout(150);
  const m = await page.evaluate(() => {
    const q = (el, s) => el.querySelector(s);
    const footer = document.querySelector('footer[role=contentinfo]');
    const main = footer.children[0];
    const bottom = footer.children[1];
    const contentRow = main.children[0];
    const subscribe = contentRow.children[0];
    const links = contentRow.children[1];
    const linksInner = links.children[0];
    const cols = [...linksInner.children];
    const r = (e) => e.getBoundingClientRect();

    // labels that wrap onto >1 line
    const wrapped = [];
    for (const col of cols) {
      for (const a of col.querySelectorAll('a, button, span[aria-label]')) {
        const txt = (a.textContent || '').trim();
        if (!txt) continue;
        const range = document.createRange();
        range.selectNodeContents(a);
        const lines = range.getClientRects().length;
        if (lines > 1) wrapped.push(txt.replace(/\s+/g, ' '));
      }
    }
    // bottom bar: is its content wider than its box?
    const bInner = bottom.children[0];
    const bKids = [...bInner.children];
    const bContent = bKids.reduce((a, k) => a + r(k).width, 0);
    const cs = getComputedStyle(bInner);
    const bAvail = r(bInner).width - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);

    return {
      docScroll: document.documentElement.scrollWidth,
      viewport: window.innerWidth,
      subscribeW: +r(subscribe).width.toFixed(1),
      linksW: +r(links).width.toFixed(1),
