cat > "$CLAUDE_JOB_DIR/tmp/verify.mjs" <<'EOF'
import { chromium } from 'playwright';
const URL='http://127.0.0.1:6099/iframe.html?id=layout-footer--default&viewMode=story';
const browser=await chromium.launch();
const page=await browser.newPage({viewport:{width:1440,height:900}});
await page.goto(URL,{waitUntil:'domcontentloaded'});
await page.waitForSelector('footer[role=contentinfo]');
await page.evaluate(()=>document.fonts.ready); await page.waitForTimeout(300);
await page.addScriptTag({content:`
  window.__lines=(el)=>{const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let r=[],n;
    while((n=w.nextNode())){if(!n.textContent.trim())continue;const g=document.createRange();
    g.selectNodeContents(n);r.push(...Array.from(g.getClientRects()).filter(x=>x.width>0&&x.height>0));}
    return r.length?new Set(r.map(x=>Math.round(x.top))).size:1;};
  window.__p=()=>{const f=document.querySelector('footer[role=contentinfo]');
    const inn=f.children[0].children[0].children[1].children[0];
    const nav=[];for(const c of inn.children)for(const a of c.querySelectorAll('a,button')){
      const t=(a.textContent||'').trim();if(t&&window.__lines(a)>1)nav.push(t.replace(/\\s+/g,' '));}
    return {nav, gap:+getComputedStyle(inn).columnGap.replace('px','')||0,
            cols:[...inn.children].map(c=>+c.getBoundingClientRect().width.toFixed(0))};};
`});
// falsification check: detector must still report the by-design wrap at 1440
await page.setViewportSize({width:1440,height:900}); await page.waitForTimeout(200);
const check=await page.evaluate(()=>window.__p());
const rows=[];
for(let w=768; w<=1024; w+=2){
  await page.setViewportSize({width:w,height:900}); await page.waitForTimeout(70);
  const p=await page.evaluate(()=>window.__p());
  rows.push({w, broken:p.nav.filter(x=>x!=='Acknowledgement of Country').length>0, gap:p.gap, cols:p.cols});
}
await browser.close();
console.log(JSON.stringify({check:check.nav, rows}));
EOF
