node "$CLAUDE_JOB_DIR/tmp/verify.mjs" > "$CLAUDE_JOB_DIR/tmp/verify.json" 2>&1; echo "exit: $?"
kill $SRV 2>/dev/null
python3 - <<'PY'
import json,os
d=json.load(open(os.environ['CLAUDE_JOB_DIR']+'/tmp/verify.json'))
print(f"\n  instrument check @1440 (expect the by-design wrap): {d['check']}")
rows=d['rows']; out=[];s=None
for r in rows:
    if r['broken'] and s is None: s=r['w']
    if not r['broken'] and s is not None: out.append((s,r['w']-2)); s=None
if s is not None: out.append((s,rows[-1]['w']))
print(f"  broken ranges now: {', '.join(f'{a}–{b}px' for a,b in out) or 'NONE'}")
print(f"  broken width:      ~{sum(b-a+2 for a,b in out)}px of 256px band  (was ~124px)")
print()
print("  gap at the old 860 boundary:")
for w in (856,858,860,862,864):
    r=[x for x in rows if x['w']==w]
    if r: print(f"    {w}px  gap={r[0]['gap']:.0f}px  cols={'/'.join(map(str,r[0]['cols']))}  {'BROKEN' if r[0]['broken'] else 'ok'}")
PY

