import { chromium } from 'playwright';
const URL='http://127.0.0.1:6099/iframe.html?id=layout-footer--default&viewMode=story';
const b=await chromium.launch(); const p=await b.newPage({viewport:{width:1440,height:1400}});
await p.goto(URL,{waitUntil:'domcontentloaded'}); await p.waitForSelector('footer[role=contentinfo]');
await p.evaluate(()=>document.fonts.ready); await p.waitForTimeout(300);
await p.addScriptTag({content:`
  window.__lines=(el)=>{const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let r=[],n;
    while((n=w.nextNode())){if(!n.textContent.trim())continue;const g=document.createRange();
    g.selectNodeContents(n);r.push(...Array.from(g.getClientRects()).filter(x=>x.width>0&&x.height>0));}
    return r.length?new Set(r.map(x=>Math.round(x.top))).size:1;};
  window.__p=()=>{const R=e=>e.getBoundingClientRect();
    const f=document.querySelector('footer[role=contentinfo]');
    const row=f.children[0].children[0], sub=row.children[0], links=row.children[1];
    const inner=links.children[0], cols=[...inner.children];
    const nav=[];for(const c of cols)for(const a of c.querySelectorAll('a,button')){
      const t=(a.textContent||'').trim();if(t&&window.__lines(a)>1)nav.push(t.replace(/\\s+/g,' '));}
    const stacked = Math.round(R(links).top) > Math.round(R(sub).bottom) - 2;
    return {stacked, subW:Math.round(R(sub).width), mapW:Math.round(R(links).width),
      sep: stacked ? Math.round(R(links).top - R(sub).bottom)
                   : Math.round(R(links).left - R(sub).right),
      colGap: cols.length>1 ? Math.round(R(cols[1]).left - R(cols[0]).right) : 0,
      wraps: nav.filter(x=>x!=='Acknowledgement of Country'),
      h: Math.round(R(f).height)};};
`});
const rows=[];
for (const w of [768,800,860,900,944,946,1000,1023,1024,1440]) {
  await p.setViewportSize({width:w,height:1400}); await p.waitForTimeout(140);
  rows.push({w, ...(await p.evaluate(()=>window.__p()))});
}
await b.close(); console.log(JSON.stringify(rows));
EOF
