import { chromium } from 'playwright';
const URL='http://127.0.0.1:6099/iframe.html?id=layout-footer--default&viewMode=story';
const b=await chromium.launch(); const p=await b.newPage({viewport:{width:1440,height:1400}});
await p.goto(URL,{waitUntil:'domcontentloaded'}); await p.waitForSelector('footer[role=contentinfo]');
await p.evaluate(()=>document.fonts.ready); await p.waitForTimeout(400);
await p.addScriptTag({content:`
  window.__lines=(el)=>{const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let r=[],n;
    while((n=w.nextNode())){if(!n.textContent.trim())continue;const g=document.createRange();
    g.selectNodeContents(n);r.push(...Array.from(g.getClientRects()).filter(x=>x.width>0&&x.height>0));}
    return r.length?new Set(r.map(x=>Math.round(x.top))).size:1;};
  window.__bb=()=>{const R=e=>e.getBoundingClientRect();
    const bar=document.querySelector('footer[role=contentinfo]').children[1];
    const inner=bar.children[0];
    const links=[...inner.querySelectorAll('a')];
    const broken=links.filter(a=>window.__lines(a)>1).map(a=>a.textContent.trim());
    // how many visual rows do the legal links occupy?
    const rows=new Set(links.map(a=>Math.round(R(a).top))).size;
    return {h:Math.round(R(inner).height), barH:Math.round(R(bar).height),
            linkRows:rows, brokenLabels:broken,
            padL:getComputedStyle(inner).paddingLeft};};
`});
const out=[];
for (const w of [768,800,860,900,908,909,946,1000,1023,1024,1440]) {
  await p.setViewportSize({width:w,height:1400}); await p.waitForTimeout(130);
  out.push({w, ...(await p.evaluate(()=>window.__bb()))});
}
await b.close(); console.log(JSON.stringify(out));
EOF
