import { chromium } from 'playwright';
const URL='http://127.0.0.1:6099/iframe.html?id=layout-footer--default&viewMode=story';
const b=await chromium.launch();
const WIDTHS=[402, 768, 900, 1023, 1440];
const out=[];
for (const w of WIDTHS) {
  const p=await b.newPage({viewport:{width:w,height:1600}});
  await p.goto(URL,{waitUntil:'domcontentloaded'});
  await p.waitForSelector('footer[role=contentinfo]');
  await p.evaluate(()=>document.fonts.ready); await p.waitForTimeout(350);
  const probe = async () => p.evaluate(()=>{
    const R=e=>e.getBoundingClientRect();
    const f=document.querySelector('footer[role=contentinfo]');
    const slot=f.querySelector('[aria-live="polite"]');
    const sub=f.children[0].children[0].children[0];
    const msg=slot.querySelector('p');
    return {slot:+R(slot).height.toFixed(1), sub:+R(sub).height.toFixed(1),
            footer:+R(f).height.toFixed(1), slotTop:+R(slot).top.toFixed(1),
            msgLines: msg ? Math.round(R(msg).height/18) : 0,
            msgW: msg ? +R(msg).width.toFixed(0) : 0};
  });
  const before = await probe();
  await p.getByLabel(/email/i).fill('shopper@example.com');
  await p.getByRole('button',{name:/subscribe/i}).click();
  await p.waitForTimeout(250);
  const after = await probe();
  out.push({w, before, after});
  await p.close();
}
await b.close(); console.log(JSON.stringify(out));
EOF
